const pacificItineraries=[{"id":"san-francisco-ca-city","title":"San Francisco, CA: Four-Day City Adventure","destination":"San Francisco, CA","state":"CA","stateName":"California","region":"San Francisco Bay Area","days":4,"tripType":"city adventure","interests":["family","museums","food","scenic","historical-sites"],"budget":2800,"budgetNote":"Est. for 2 adults + 2 kids: 3 nights mid-range hotel, meals, transit, and attraction tickets.","tagline":"Cable cars, sea lions, and the world's most famous bridge \u2014 the city by the bay was made for family adventures.","overview":"San Francisco packs an enormous amount of kid-friendly fun into 49 square miles. Ride a rattling cable car up Nob Hill, watch sea lions bark at PIER 39, and walk (partway!) across the Golden Gate Bridge as fog rolls through. Between the hands-on museums and the clam chowder in sourdough bowls, four days fly by. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk or bike partway across the Golden Gate Bridge","Watch the sea lions haul out at PIER 39's K-Dock","Touch a stingray at the California Academy of Sciences","Ride a historic cable car from Powell & Market","Tinker with 650+ exhibits at the Exploratorium"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 5+. Hills are steep \u2014 bring a carrier for toddlers and plan cable-car rides to save little legs.","lat":37.77712,"lng":-122.41966,"itinerary":[{"day":1,"title":"Icons of the Bay","morning":{"stop":"Golden Gate Bridge Welcome Center","description":"Start at the south end of the bridge for the classic postcard view. Walk the first span with the kids \u2014 the fog horns and sailboats below keep everyone entertained. The visitor center has a great bridge-building exhibit.","cost":"Free (parking ~$8 est.) (est.)","time":"9:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Fisherman's Wharf & PIER 39","description":"Grab clam chowder in a sourdough bowl and stroll to PIER 39. The sea lions at K-Dock are the main event \u2014 kids can watch them wrestle and bark for an hour. Street performers and the carousel round out the afternoon.","cost":"$60\u2013$90 for lunch (est.)","time":"12:30 PM \u2013 4:30 PM"},"evening":{"stop":"Cable car ride & dinner","description":"Hop a Powell-Hyde cable car at the turnaround for the full rattling ride over the hills. End the day with dinner near Union Square and an early night \u2014 you'll need the rest.","cost":"$32/adult, $16/child one-way (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Science Day in Golden Gate Park","morning":{"stop":"California Academy of Sciences","description":"One building holds an aquarium, a planetarium, a rainforest dome, and a living roof with wildflowers. The albino alligator Claude is a kid legend. Arrive at opening to beat the crowds.","cost":"$46/adult, $36/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Golden Gate Park & lunch","description":"Picnic or grab lunch at the park's food trucks, then let the kids run at the Koret Children's Quarter playground \u2014 home of the historic 1914 carousel. Rent a surrey bike if little legs are tired.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Painted Ladies & dinner","description":"Walk to Alamo Square for the famous Painted Ladies row at golden hour. Dinner in the Inner Sunset or Haight-Ashbury, both full of casual family spots.","cost":"$50\u2013$80 for dinner (est.)","time":"4:30 PM \u2013 7:30 PM"}},{"day":3,"title":"Tinkering at the Exploratorium","morning":{"stop":"Exploratorium","description":"This is not a quiet museum \u2014 kids pull, crank, splash, and build through 650+ hands-on exhibits. The Tactile Dome (ages 8+) is a pitch-black climbing maze that's unforgettable. Plan at least four hours.","cost":"$35/adult, $25/child (est.)","time":"10:00 AM \u2013 2:00 PM"},"afternoon":{"stop":"Ferry Building & Embarcadero","description":"Walk the Embarcadero to the Ferry Building for lunch from its artisan food stalls \u2014 cowboy-style sandwiches, oysters, and the famous Blue Bottle coffee. Kids love watching the ferries come and go.","cost":"$45\u2013$70 for lunch (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Chinatown evening stroll","description":"Wander through the Chinatown gates for dinner \u2014 dim sum and fortune cookies make an easy, fun family meal. Pick up souvenirs on Grant Avenue before heading back.","cost":"$45\u2013$70 for dinner (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":4,"title":"Sausalito & Farewell Views","morning":{"stop":"Ferry to Sausalito","description":"Take the ferry from Pier 41 across the bay \u2014 the skyline views beat any postcard. In Sausalito, stroll the waterfront, browse the shops, and visit the Bay Area Discovery Museum if the kids want one more play stop.","cost":"$14/adult, $7/child ferry (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Palace of Fine Arts","description":"Ferry back and head to the Palace of Fine Arts \u2014 its dreamy rotunda and lagoon with swans feel like a movie set. Perfect picnic spot and final photo op.","cost":"Free (est.)","time":"1:00 PM \u2013 3:00 PM"},"evening":{"stop":"Twin Peaks sunset","description":"Drive or rideshare up to Twin Peaks for a 360-degree farewell view of the whole city. Grab a casual farewell dinner on the way to the hotel.","cost":"$25\u2013$40 rideshare (est.)","time":"4:00 PM \u2013 7:00 PM"}}],"attractions":[{"name":"Golden Gate Bridge","description":"The 1.7-mile orange span is the symbol of San Francisco \u2014 and walking it is free. The Welcome Center at the south end has exhibits on how the bridge was built, and Battery Spencer on the Marin side gives the classic full-bridge photo.","officialUrl":"https://www.goldengate.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Golden+Gate+Bridge+San+Francisco+CA","price":"Free; parking ~$8 (est.)","photos":["assets/pacific/images/san-francisco-ca-city/attr1-1.jpg","assets/pacific/images/san-francisco-ca-city/attr1-2.jpg","assets/pacific/images/san-francisco-ca-city/attr1-3.jpg","assets/pacific/images/san-francisco-ca-city/attr1-4.jpg"]},{"name":"PIER 39","description":"San Francisco's famous waterfront marketplace, home to the noisy sea lion colony at K-Dock, a two-story carousel, street performers, and bay-view restaurants. The Aquarium of the Bay is right here too for a rainy-hour detour.","officialUrl":"https://www.pier39.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=PIER+39+San+Francisco+CA","price":"Free entry; attractions $10\u2013$35 (est.)","photos":["assets/pacific/images/san-francisco-ca-city/attr2-1.jpg","assets/pacific/images/san-francisco-ca-city/attr2-2.jpg","assets/pacific/images/san-francisco-ca-city/attr2-3.jpg","assets/pacific/images/san-francisco-ca-city/attr2-4.jpg"]},{"name":"California Academy of Sciences","description":"A natural-history museum, aquarium, planetarium, and rainforest all under one living roof in Golden Gate Park. Highlights for kids: the four-story rainforest dome, the coral reef tank, and Claude the albino alligator.","officialUrl":"https://www.calacademy.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=California+Academy+of+Sciences+San+Francisco+CA","price":"$46/adult, $36/child (est.)","photos":["assets/pacific/images/san-francisco-ca-city/attr3-1.jpg","assets/pacific/images/san-francisco-ca-city/attr3-2.jpg","assets/pacific/images/san-francisco-ca-city/attr3-3.jpg","assets/pacific/images/san-francisco-ca-city/attr3-4.jpg"]},{"name":"Exploratorium","description":"A legendary hands-on science museum on the waterfront with 650+ exhibits you can touch, build, and climb through. The pitch-black Tactile Dome maze (ages 8+) and the outdoor fog bridge are unforgettable.","officialUrl":"https://www.exploratorium.edu","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Exploratorium+San+Francisco+CA","price":"$35/adult, $25/child (est.)","photos":["assets/pacific/images/san-francisco-ca-city/attr4-1.jpg","assets/pacific/images/san-francisco-ca-city/attr4-2.jpg","assets/pacific/images/san-francisco-ca-city/attr4-3.jpg","assets/pacific/images/san-francisco-ca-city/attr4-4.jpg"]}],"restaurants":[{"name":"Boudin Bakery Caf\u00e9","detail":"Clam chowder served in a sourdough bread bowl at Fisherman's Wharf \u2014 the classic SF kid meal.","price":"$$"},{"name":"Scoma's","detail":"Waterfront seafood institution on Alcatraz Ave with bay views and a kids' menu.","price":"$$$"},{"name":"Tommy's Joynt","detail":"Old-school cafeteria-style spot serving turkey legs and roast beef since 1947 \u2014 fast, cheap, fun.","price":"$"}],"rainyDay":["California Academy of Sciences (all indoors)","Exploratorium (all indoors)","San Francisco Cable Car Museum (free, in the historic powerhouse)"],"driveNotes":"You don't need a car in the city itself \u2014 parking is expensive and hills are brutal. Use Muni, cable cars, and rideshares, and rent a car only for day trips. If driving in, most downtown hotels charge $50\u2013$70/night for parking (est.).","related":["los-angeles-ca-city","yosemite-ca-nature","lake-tahoe-ca-lake"],"imageAsset":"assets/pacific/images/san-francisco-ca-city/hero.jpg"},{"id":"los-angeles-ca-city","title":"Los Angeles, CA: Four-Day City Adventure","destination":"Los Angeles, CA","state":"CA","stateName":"California","region":"Southern California","days":4,"tripType":"city adventure","interests":["family","museums","food","beaches","scenic"],"budget":2600,"budgetNote":"Est. for 2 adults + 2 kids: 3 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"Stars on the sidewalk, dinosaurs in tar, and telescopes above the city \u2014 LA is a theme park disguised as a city.","overview":"Los Angeles rewards families who plan around its sprawl: pick one area per day and you'll dodge the worst traffic. Stargaze at Griffith Observatory, scream on the Santa Monica Pier roller coaster, and stand next to real mammoth fossils at the La Brea Tar Pits. With beaches, museums, and movie magic, four days barely scratch the surface. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["See the Hollywood Sign from Griffith Observatory's lawn","Ride the Ferris wheel over the Pacific at Santa Monica Pier","Stand beside Ice Age mammoths at the La Brea Tar Pits","Wander the Getty Center's gardens and kid-friendly art","Spot stars on the Walk of Fame in Hollywood"],"bestSeason":"Year-round","familyFriendly":"Best for ages 5+. LA is car-dependent \u2014 a rental car or rideshares are essential, and cluster each day in one neighborhood.","lat":34.05357,"lng":-118.24545,"itinerary":[{"day":1,"title":"Hollywood & Griffith","morning":{"stop":"Griffith Observatory","description":"Arrive early for free parking and walk the lawn for the best Hollywood Sign photo in the city. Inside, the pendulum, Tesla coil, and planetarium shows thrill kids \u2014 and the city views from the terraces are unreal.","cost":"Free entry; planetarium $7\u2013$10 (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Hollywood Walk of Fame","description":"Drive down to Hollywood Boulevard for lunch and a stroll past the stars. The TCL Chinese Theatre's handprints \u2014 from Mickey Mouse to movie heroes \u2014 are the kid favorite.","cost":"$50\u2013$75 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Griffith Park merry-go-round","description":"End the day back in Griffith Park at the historic 1926 merry-go-round and Travel Town train museum. Casual dinner in Los Feliz on the way back.","cost":"$3/ride (est.)","time":"4:30 PM \u2013 7:30 PM"}},{"day":2,"title":"Tar Pits & the Getty","morning":{"stop":"La Brea Tar Pits","description":"Watch real excavations bubble in the asphalt lake, then meet mammoths, saber-toothed cats, and dire wolves in the museum. The 3D movie about the Ice Age is a kid hit.","cost":"$18/adult, $8/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"The Original Farmers Market & The Grove","description":"Lunch at the 1934 Farmers Market \u2014 dozens of stalls, from crepes to Cajun. The adjacent Grove has a dancing fountain and a free trolley the kids will beg to ride.","cost":"$45\u2013$65 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"The Getty Center","description":"Ride the tram up the hill to world-class art, stunning gardens, and some of LA's best sunset views. The family room has hands-on art activities, and admission is free.","cost":"Free; parking $25 (est.)","time":"4:00 PM \u2013 7:30 PM"}},{"day":3,"title":"Santa Monica Beach Day","morning":{"stop":"Santa Monica Pier","description":"Ride the solar-powered Ferris wheel and the historic carousel, then walk the pier for street performers and ocean views. The Heal the Bay Aquarium underneath the pier is a perfect small stop.","cost":"Ride tickets $5\u2013$10 each (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Beach afternoon","description":"Claim a spot on the wide sandy beach for swimming, sandcastles, and the Muscle Beach playground. Rent bikes to cruise the beach path toward Venice.","cost":"Bike rentals ~$15/hr (est.)","time":"1:00 PM \u2013 5:00 PM"},"evening":{"stop":"Third Street Promenade dinner","description":"Stroll the pedestrian promenade for dinner and window shopping. The dinosaur topiaries are a fun photo stop for kids.","cost":"$50\u2013$80 for dinner (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":4,"title":"Natural History & Farewell","morning":{"stop":"Natural History Museum","description":"The dinosaur hall \u2014 with a T. rex growth series \u2014 and the butterfly pavilion (seasonal) are the headliners. The nature gardens outside are free and lovely.","cost":"$18/adult, $7/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Exposition Park & lunch","description":"Picnic in the park or grab lunch nearby, then let the kids burn energy at the park playgrounds. The Science Center next door is free if you want one more museum.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Griffith Observatory at night","description":"Return to the observatory after dark to look through the public telescopes \u2014 Saturn's rings through the Zeiss telescope are unforgettable. A perfect farewell to LA.","cost":"Free (est.)","time":"7:00 PM \u2013 9:30 PM"}}],"attractions":[{"name":"Griffith Observatory","description":"LA's beloved hilltop observatory with free admission, planetarium shows, live telescope viewing, and the best Hollywood Sign and city views anywhere. The Tesla coil demonstrations spark literally.","officialUrl":"https://www.griffithobservatory.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Griffith+Observatory+Los+Angeles+CA","price":"Free; planetarium $7\u2013$10 (est.)","photos":["assets/pacific/images/los-angeles-ca-city/attr1-1.jpg","assets/pacific/images/los-angeles-ca-city/attr1-2.jpg","assets/pacific/images/los-angeles-ca-city/attr1-3.jpg","assets/pacific/images/los-angeles-ca-city/attr1-4.jpg"]},{"name":"Santa Monica Pier","description":"The historic 1909 pier with Pacific Park amusement rides \u2014 including a solar-powered Ferris wheel \u2014 plus an aquarium, carousel, and endless ocean views. The beach below is wide, sandy, and lifeguarded.","officialUrl":"https://www.santamonicapier.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Santa+Monica+Pier+Santa+Monica+CA","price":"Free entry; rides $5\u2013$10 (est.)","photos":["assets/pacific/images/los-angeles-ca-city/attr2-1.jpg","assets/pacific/images/los-angeles-ca-city/attr2-2.jpg","assets/pacific/images/los-angeles-ca-city/attr2-3.jpg","assets/pacific/images/los-angeles-ca-city/attr2-4.jpg"]},{"name":"The Getty Center","description":"A hilltop campus of art, architecture, and gardens reached by a fun tram ride. Admission is free, the family room offers hands-on art projects, and the Central Garden is a maze of color kids love exploring.","officialUrl":"https://www.getty.edu","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The+Getty+Center+Los+Angeles+CA","price":"Free; parking $25 (est.)","photos":["assets/pacific/images/los-angeles-ca-city/attr3-1.jpg","assets/pacific/images/los-angeles-ca-city/attr3-2.jpg","assets/pacific/images/los-angeles-ca-city/attr3-3.jpg","assets/pacific/images/los-angeles-ca-city/attr3-4.jpg"]},{"name":"La Brea Tar Pits","description":"The world's most famous Ice Age fossil site, right in the middle of the city. Watch tar bubble in the lake pits, see active excavations, and meet mammoths and saber-toothed cats in the museum.","officialUrl":"https://www.tarpits.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=La+Brea+Tar+Pits+Los+Angeles+CA","price":"$18/adult, $8/child (est.)","photos":["assets/pacific/images/los-angeles-ca-city/attr4-1.jpg","assets/pacific/images/los-angeles-ca-city/attr4-2.jpg","assets/pacific/images/los-angeles-ca-city/attr4-3.jpg","assets/pacific/images/los-angeles-ca-city/attr4-4.jpg"]}],"restaurants":[{"name":"Philippe The Original","detail":"Home of the French dip sandwich since 1908 \u2014 sawdust floors, fast lines, kid-approved.","price":"$"},{"name":"In-N-Out Burger","detail":"The California classic \u2014 Double-Doubles and animal-style fries the kids will remember.","price":"$"},{"name":"Randy's Donuts","detail":"Giant rooftop donut and legendary raised glazed \u2014 a worthy roadside pilgrimage.","price":"$"}],"rainyDay":["Natural History Museum of Los Angeles County","California Science Center (free entry)","Griffith Observatory (mostly indoors)"],"driveNotes":"LA is built for cars \u2014 rent one and plan around rush hour (7\u20139 AM, 4\u20137 PM). Distances look short but take 45+ minutes; cluster each day in one area. Hotel parking often runs $25\u2013$45/night (est.).","related":["san-diego-ca-city","san-francisco-ca-city","lake-tahoe-ca-lake"],"imageAsset":"assets/pacific/images/los-angeles-ca-city/hero.jpg"},{"id":"san-diego-ca-city","title":"San Diego, CA: Three-Day Family Adventure","destination":"San Diego, CA","state":"CA","stateName":"California","region":"Southern California","days":3,"tripType":"family adventure","interests":["family","museums","beaches","nature","historical-sites"],"budget":1900,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"World-famous zoo by morning, battleship by afternoon, and tacos by the bay at sunset.","overview":"San Diego is America's most easygoing big city \u2014 sunny, flat, and built for families. The world-famous zoo and Balboa Park's museums fill a full day, the USS Midway lets kids climb through a real aircraft carrier, and Cabrillo's tide pools turn low tide into a treasure hunt. Three relaxed days here feel like a week anywhere else. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride the Skyfari tram over the San Diego Zoo","Climb through a real aircraft carrier on the USS Midway","Hunt for sea stars in Cabrillo's tide pools","Explore Balboa Park's Spanish-style plazas and museums","Watch the sunset over the Pacific at Sunset Cliffs"],"bestSeason":"March\u2013November","familyFriendly":"Best for all ages. Flat, stroller-friendly, and sunny \u2014 an ideal first big-city trip with toddlers.","lat":32.71568,"lng":-117.16171,"itinerary":[{"day":1,"title":"Zoo Day","morning":{"stop":"San Diego Zoo","description":"Arrive at opening and head straight to the pandas and polar bears before crowds build. The Skyfari aerial tram gives a bird's-eye view of the whole park \u2014 ride it both ways. The guided bus tour is a great rest for little legs.","cost":"$76/adult, $66/child (est.)","time":"9:00 AM \u2013 3:00 PM"},"afternoon":{"stop":"Balboa Park stroll","description":"Walk off zoo legs through Balboa Park's palm-lined plazas. Peek into the free Botanical Building with its 2,100 tropical plants, and let the kids splash in the fountains.","cost":"Free (est.)","time":"3:00 PM \u2013 5:30 PM"},"evening":{"stop":"Dinner in the Gaslamp","description":"Head to the historic Gaslamp Quarter for dinner \u2014 plenty of family-friendly patios. An evening stroll along the Embarcadero caps the day.","cost":"$55\u2013$85 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Ships & History","morning":{"stop":"USS Midway Museum","description":"Climb aboard the longest-serving U.S. aircraft carrier of the 20th century. Kids can sit in cockpits, try flight simulators, and earn junior-pilot wings on the self-guided audio tour.","cost":"$34/adult, $24/child (est.)","time":"10:00 AM \u2013 2:00 PM"},"afternoon":{"stop":"Seaport Village & harbor","description":"Lunch at Seaport Village's waterfront eateries, then watch the harbor seals and browse the shops. The historic Star of India ship is docked nearby if little sailors want more.","cost":"$45\u2013$65 for lunch (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Sunset Cliffs","description":"Drive to Sunset Cliffs Natural Park for the golden-hour show \u2014 waves crashing on sandstone cliffs. Bring a picnic or grab fish tacos on the way.","cost":"Free (est.)","time":"5:30 PM \u2013 7:30 PM"}},{"day":3,"title":"Tide Pools & Farewell","morning":{"stop":"Cabrillo National Monument","description":"Time your visit for low tide and explore the rocky tide pools \u2014 sea stars, anemones, and scuttling crabs. Tour the Old Point Loma Lighthouse and take in the sweeping bay-to-ocean view.","cost":"$20/vehicle (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Old Town San Diego","description":"Lunch in the birthplace of California \u2014 mariachi music, handmade tortillas, and historic adobe buildings. The free state park museums are quick, fun stops.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Coronado Beach evening","description":"Cross the soaring bridge to Coronado for a final beach walk by the iconic Hotel del Coronado. The wide, flat beach is perfect for one last sandcastle session.","cost":"Free (est.)","time":"4:30 PM \u2013 7:00 PM"}}],"attractions":[{"name":"San Diego Zoo","description":"One of the world's great zoos, home to 12,000 animals across 100 acres of canyon gardens. Don't miss the pandas, the Skyfari aerial tram, and the Africa Rocks exhibits with penguins and leopards.","officialUrl":"https://www.sandiegozoo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=San+Diego+Zoo+San+Diego+CA","price":"$76/adult, $66/child (est.)","photos":["assets/pacific/images/san-diego-ca-city/attr1-1.jpg","assets/pacific/images/san-diego-ca-city/attr1-2.jpg","assets/pacific/images/san-diego-ca-city/attr1-3.jpg","assets/pacific/images/san-diego-ca-city/attr1-4.jpg"]},{"name":"Balboa Park","description":"A 1,200-acre cultural park with Spanish Colonial Revival architecture, 17 museums, and lush gardens. The free Botanical Building and the Spanish Village art studios are easy family wins.","officialUrl":"https://www.balboapark.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Balboa+Park+San+Diego+CA","price":"Park free; museums $10\u2013$25 (est.)","photos":["assets/pacific/images/san-diego-ca-city/attr2-1.jpg","assets/pacific/images/san-diego-ca-city/attr2-2.jpg","assets/pacific/images/san-diego-ca-city/attr2-3.jpg","assets/pacific/images/san-diego-ca-city/attr2-4.jpg"]},{"name":"USS Midway Museum","description":"A floating city: tour the flight deck, hangar, and below-deck living quarters of this retired aircraft carrier. The self-guided audio tour (narrated by real sailors) and 30 restored aircraft keep kids hooked for hours.","officialUrl":"https://www.midway.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=USS+Midway+Museum+San+Diego+CA","price":"$34/adult, $24/child (est.)","photos":["assets/pacific/images/san-diego-ca-city/attr3-1.jpg","assets/pacific/images/san-diego-ca-city/attr3-2.jpg","assets/pacific/images/san-diego-ca-city/attr3-3.jpg","assets/pacific/images/san-diego-ca-city/attr3-4.jpg"]},{"name":"Cabrillo National Monument","description":"Perched on Point Loma with bay-to-Pacific panoramas, this park honors the first European to land on the West Coast. The real draw for families: spectacular tide pools at low tide and the 1855 lighthouse.","officialUrl":"https://www.nps.gov/cabr","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cabrillo+National+Monument+San+Diego+CA","price":"$20/vehicle (est.)","photos":["assets/pacific/images/san-diego-ca-city/attr4-1.jpg","assets/pacific/images/san-diego-ca-city/attr4-2.jpg","assets/pacific/images/san-diego-ca-city/attr4-3.jpg","assets/pacific/images/san-diego-ca-city/attr4-4.jpg"]}],"restaurants":[{"name":"Hodad's","detail":"Legendary Ocean Beach burger joint \u2014 massive burgers, surf decor, zero pretense.","price":"$"},{"name":"The Fish Market","detail":"Waterfront seafood with harbor views downtown; the kids' menu and clam chowder deliver.","price":"$$"},{"name":"Old Town Mexican Caf\u00e9","detail":"Handmade tortillas and mariachis in Old Town \u2014 festive and family-perfect.","price":"$$"}],"rainyDay":["USS Midway Museum (mostly indoors)","Fleet Science Center in Balboa Park","San Diego Natural History Museum"],"driveNotes":"San Diego is an easy driving city with free highway parking at most beaches. The zoo and Balboa Park share big lots ($0\u2013$15 est.). Everything on this itinerary is within 20 minutes of downtown \u2014 no LA-style traffic dread.","related":["los-angeles-ca-city","san-francisco-ca-city","oahu-hi-beach"],"imageAsset":"assets/pacific/images/san-diego-ca-city/hero.jpg"},{"id":"yosemite-ca-nature","title":"Yosemite, CA: Three-Day Nature Escape","destination":"Yosemite, CA","state":"CA","stateName":"California","region":"Sierra Nevada","days":3,"tripType":"nature escape","interests":["family","outdoors","nature","scenic"],"budget":1400,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights in-park lodge or nearby motel, meals, park entry, and gas.","tagline":"Waterfalls that thunder, cliffs that dwarf skyscrapers, and trees older than empires.","overview":"Yosemite Valley's granite walls stop first-timers cold \u2014 photos don't prepare you. Three days gives you the valley's greatest hits, a walk among 3,000-year-old sequoias, and a sunset from Glacier Point that your kids will talk about for years. Book lodging months ahead; the park fills fast. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Feel the mist of Vernal Fall on the Mist Trail","Walk among giant sequoias in Mariposa Grove","Watch sunset paint Half Dome from Glacier Point","Spot deer and climbers in Yosemite Valley meadows","Stargaze in some of America's darkest skies"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 6+. Valley shuttle is stroller-friendly; pick short trails (Lower Yosemite Fall, Cook's Meadow) for little hikers.","lat":37.72128,"lng":-119.62627,"itinerary":[{"day":1,"title":"Valley Icons","morning":{"stop":"Tunnel View & valley floor","description":"Stop at Tunnel View for the classic El Capitan\u2013Half Dome panorama, then ride the free valley shuttle. Walk the easy Lower Yosemite Fall loop (1 mile) and let the kids wade in the Merced River at Sentinel Beach.","cost":"$35/vehicle park entry (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Yosemite Village & lunch","description":"Lunch at the village, then visit the Yosemite Museum and the Ansel Adams Gallery. Kids can join the free Junior Ranger program at the visitor center \u2014 the badge ceremony is a highlight.","cost":"$45\u2013$65 for lunch (est.)","time":"1:00 PM \u2013 4:30 PM"},"evening":{"stop":"Cook's Meadow sunset","description":"An easy evening stroll through Cook's Meadow as the light turns the cliffs gold. Dinner at the lodge, then stargazing \u2014 the Milky Way shows up on clear nights.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 9:00 PM"}},{"day":2,"title":"Waterfalls & Giants","morning":{"stop":"Mist Trail to Vernal Fall footbridge","description":"Hike the paved first mile of the Mist Trail to the Vernal Fall footbridge (1.6 miles round trip) \u2014 big waterfall payoff for moderate effort. Bring rain jackets; the mist lives up to the name in spring.","cost":"Free (est.)","time":"8:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Mariposa Grove","description":"Drive south to the Mariposa Grove and walk the Lower Grove trail among 500 giant sequoias, including the Grizzly Giant. The free shuttle runs from the welcome plaza.","cost":"Free (est.)","time":"2:00 PM \u2013 5:30 PM"},"evening":{"stop":"Glacier Point sunset","description":"Drive up to Glacier Point for sunset \u2014 Half Dome glows orange and the whole valley spreads below. This is the single most jaw-dropping viewpoint in the park.","cost":"Free (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":3,"title":"Meadows & Farewell","morning":{"stop":"Mirror Lake loop","description":"An easy morning walk to Mirror Lake, which reflects Half Dome like glass in spring. Great for spotting deer and letting kids skip stones.","cost":"Free (est.)","time":"9:00 AM \u2013 11:30 AM"},"afternoon":{"stop":"El Capitan meadows","description":"Set up at El Cap Meadow with binoculars and watch rock climbers inch up the 3,000-foot wall \u2014 kids are mesmerized. Picnic lunch with the best view in the park.","cost":"$30\u2013$45 picnic supplies (est.)","time":"12:00 PM \u2013 3:00 PM"},"evening":{"stop":"Valley Chapel & exit","description":"A quiet final stop at the tiny Yosemite Chapel, then one last Tunnel View photo on the way out. Grab dinner in Mariposa or Oakhurst on the drive home.","cost":"$40\u2013$60 for dinner (est.)","time":"3:30 PM \u2013 6:00 PM"}}],"attractions":[{"name":"Yosemite Valley & Tunnel View","description":"The heart of the park: Tunnel View's panorama, El Capitan's 3,000-foot wall, and Yosemite Falls \u2014 North America's tallest waterfall. Free shuttles connect every major stop, and the valley trails are mostly flat and easy.","officialUrl":"https://www.nps.gov/yose","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Yosemite+Valley+%26+Tunnel+View+Yosemite+National+Park+CA","price":"$35/vehicle entry (est.)","photos":["assets/pacific/images/yosemite-ca-nature/attr1-1.jpg","assets/pacific/images/yosemite-ca-nature/attr1-2.jpg","assets/pacific/images/yosemite-ca-nature/attr1-3.jpg","assets/pacific/images/yosemite-ca-nature/attr1-4.jpg"]},{"name":"Mariposa Grove of Giant Sequoias","description":"Five hundred mature giant sequoias, some 3,000 years old, in the park's southern corner. The Lower Grove trail is an easy 2-mile walk past the Grizzly Giant and the California Tunnel Tree.","officialUrl":"https://www.nps.gov/yose","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mariposa+Grove+of+Giant+Sequoias+Yosemite+National+Park+CA","price":"Included with entry (est.)","photos":["assets/pacific/images/yosemite-ca-nature/attr2-1.jpg","assets/pacific/images/yosemite-ca-nature/attr2-2.jpg","assets/pacific/images/yosemite-ca-nature/attr2-3.jpg","assets/pacific/images/yosemite-ca-nature/attr2-4.jpg"]},{"name":"Glacier Point","description":"A 7,214-foot overlook with the park's most famous view: Half Dome, Vernal and Nevada Falls, and the High Sierra in one sweep. Sunset here is legendary \u2014 arrive an hour early for parking.","officialUrl":"https://www.nps.gov/yose","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Glacier+Point+Yosemite+National+Park+CA","price":"Included with entry (est.)","photos":["assets/pacific/images/yosemite-ca-nature/attr3-1.jpg","assets/pacific/images/yosemite-ca-nature/attr3-2.jpg","assets/pacific/images/yosemite-ca-nature/attr3-3.jpg","assets/pacific/images/yosemite-ca-nature/attr3-4.jpg"]},{"name":"Mist Trail to Vernal Fall","description":"Yosemite's signature hike: a paved, stair-stepped trail climbing alongside Vernal Fall. The 1.6-mile round trip to the footbridge suits fit families; the full 3-mile trip to the top is for strong hikers only.","officialUrl":"https://www.nps.gov/yose","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mist+Trail+to+Vernal+Fall+Yosemite+National+Park+CA","price":"Included with entry (est.)","photos":["assets/pacific/images/yosemite-ca-nature/attr4-1.jpg","assets/pacific/images/yosemite-ca-nature/attr4-2.jpg","assets/pacific/images/yosemite-ca-nature/attr4-3.jpg","assets/pacific/images/yosemite-ca-nature/attr4-4.jpg"]}],"restaurants":[{"name":"The Ahwahnee Dining Room","detail":"Grand historic dining room \u2014 worth one splurge dinner; reservations essential.","price":"$$$"},{"name":"Degnan's Kitchen","detail":"Casual cafeteria in Yosemite Village with pizza, sandwiches, and grab-and-go.","price":"$"},{"name":"Mountain Room Restaurant","detail":"Yosemite Valley Lodge spot with big windows facing the falls; solid family fare.","price":"$$"}],"rainyDay":["Yosemite Museum & visitor center films","Ansel Adams Gallery","Indian Village indoor exhibits"],"driveNotes":"Book in-park lodging 6\u201312 months ahead \u2014 it sells out. Summer requires a day-use reservation for the park (check nps.gov). Gas up before entering; there are no stations in the valley. Chains may be required on park roads in shoulder seasons.","related":["lake-tahoe-ca-lake","san-francisco-ca-city","mount-rainier-wa-nature"],"imageAsset":"assets/pacific/images/yosemite-ca-nature/hero.jpg"},{"id":"lake-tahoe-ca-lake","title":"Lake Tahoe, CA: Three-Day Mountain Retreat","destination":"Lake Tahoe, CA","state":"CA","stateName":"California","region":"Sierra Nevada","days":3,"tripType":"mountain retreat","interests":["family","outdoors","nature","beaches","scenic"],"budget":1700,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, beach parking, and one lift/gondola ride.","tagline":"Water so blue it looks Photoshopped, beaches with mountain views, and alpine adventure for every age.","overview":"Lake Tahoe's impossibly blue water sits ringed by Sierra peaks, and summer turns it into the West's best family lake. Swim at Sand Harbor's granite coves, circle Emerald Bay's island castle, and ride the gondola up for a bird's-eye view. In winter the same trip swaps beaches for ski slopes. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Swim in the turquoise coves of Sand Harbor","Tour Vikingsholm castle on Emerald Bay's shore","Ride the Heavenly gondola for panoramic lake views","Build sandcastles at Kings Beach with mountain views","Kayak the crystal-clear east shore"],"bestSeason":"June\u2013September, December\u2013March","familyFriendly":"Best for all ages. Beaches are calm and shallow at the edges; the gondola and easy lakeside paths suit strollers.","lat":38.91163,"lng":-120.00781,"itinerary":[{"day":1,"title":"East Shore Beaches","morning":{"stop":"Sand Harbor","description":"Arrive by 10 AM \u2014 the parking lot fills fast. Granite boulders, shallow turquoise coves, and a sandy beach made for kids. Bring a picnic; the snack bar lines get long.","cost":"$10\u2013$15 parking (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Lunch & lakeside path","description":"Lunch in Incline Village, then walk part of the paved East Shore Trail \u2014 stunning lake views with benches every few minutes for little legs.","cost":"$45\u2013$65 for lunch (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Kings Beach evening","description":"End the day at Kings Beach \u2014 the north shore's biggest, sandiest beach. Evening light on the water is gorgeous, and the playground backs the sand.","cost":"Free (est.)","time":"5:00 PM \u2013 7:30 PM"}},{"day":2,"title":"Emerald Bay","morning":{"stop":"Emerald Bay State Park","description":"Drive the west shore to Emerald Bay overlook \u2014 Tahoe's most photographed view. Hike the 1-mile trail down to Vikingsholm, a 1929 Scandinavian castle, for a tour.","cost":"$10 parking (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Vikingsholm tour & swim","description":"Tour the castle's great room and courtyard, then swim or kayak around Fannette Island \u2014 Tahoe's only island, with a tiny stone teahouse on top.","cost":"Castle tour $20/adult, $10/child (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Tahoe City dinner","description":"Drive the scenic west shore to Tahoe City for dinner. Stroll the shops and watch the sunset paint the lake pink.","cost":"$55\u2013$80 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":3,"title":"Gondola & Farewell","morning":{"stop":"Heavenly gondola","description":"Ride the 2.4-mile gondola from Heavenly Village up the mountain \u2014 the lake unfolds below like a map. At the top: the observation deck, tubing hill (summer), and hiking trails.","cost":"$59/adult, $36/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Heavenly Village lunch","description":"Lunch in the village, then let the kids loose on the mini-golf and climbing wall. The shops are fun for souvenir hunting.","cost":"$45\u2013$65 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Nevada Beach sunset","description":"One last swim at Nevada Beach's gentle shoreline, then watch the sun drop behind the Sierras. Grab takeout pizza for a beach picnic farewell.","cost":"$35\u2013$50 takeout (est.)","time":"4:30 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Emerald Bay State Park","description":"Tahoe's crown jewel: a sapphire bay with a tiny island, framed by granite cliffs. Hike down to Vikingsholm, a 1929 Scandinavian-style mansion offering summer tours, and kayak out to Fannette Island.","officialUrl":"https://www.parks.ca.gov/?page_id=506","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Emerald+Bay+State+Park+South+Lake+Tahoe+CA","price":"$10 parking (est.)","photos":["assets/pacific/images/lake-tahoe-ca-lake/attr1-1.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr1-2.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr1-3.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr1-4.jpg"]},{"name":"Sand Harbor","description":"Lake Tahoe Nevada State Park's most beloved beach \u2014 smooth granite boulders, shallow turquoise water, and a sandy swim area. Arrive before 10 AM in summer; the lot closes when full.","officialUrl":"https://parks.nv.gov/parks/lake-tahoe-nevada-state-park","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sand+Harbor+Incline+Village+NV","price":"$10\u2013$15 parking (est.)","photos":["assets/pacific/images/lake-tahoe-ca-lake/attr2-1.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr2-2.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr2-3.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr2-4.jpg"]},{"name":"Heavenly Mountain Resort","description":"The big mountain straddling the California-Nevada line. Summer brings the scenic gondola, observation deck, tubing, and hiking; winter brings 97 trails of skiing. The views from the top never get old.","officialUrl":"https://www.skiheavenly.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Heavenly+Mountain+Resort+South+Lake+Tahoe+CA","price":"Gondola $59/adult, $36/child (est.)","photos":["assets/pacific/images/lake-tahoe-ca-lake/attr3-1.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr3-2.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr3-3.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr3-4.jpg"]},{"name":"Kings Beach","description":"The north shore's largest public beach \u2014 wide sand, gentle entry, mountain views, and a playground right off the sand. The adjacent town has the lake's best cluster of casual family restaurants.","officialUrl":"https://www.northtahoebusiness.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kings+Beach+Kings+Beach+CA","price":"Free (est.)","photos":["assets/pacific/images/lake-tahoe-ca-lake/attr4-1.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr4-2.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr4-3.jpg","assets/pacific/images/lake-tahoe-ca-lake/attr4-4.jpg"]}],"restaurants":[{"name":"Gar Woods Grill & Pier","detail":"Lakeside institution on Carnelian Bay \u2014 famous Wet Woody cocktails for parents, kids' menu and pier views.","price":"$$"},{"name":"Base Camp Pizza Co.","detail":"Climbing-gym-meets-pizzeria in Heavenly Village; loud, fun, and kid-approved.","price":"$"},{"name":"Riva Grill","detail":"South shore lakeside dining with beach access \u2014 great fish tacos at sunset.","price":"$$"}],"rainyDay":["Tahoe Science Center (Incline Village)","Heavenly Village ice skating & movies","National Automobile Museum (day trip to Reno)"],"driveNotes":"Summer weekends bring heavy traffic on Highway 50 and around Emerald Bay \u2014 start early. In winter, carry chains; they're often required over the passes. Parking at popular beaches fills by 10\u201311 AM in July and August.","related":["yosemite-ca-nature","san-francisco-ca-city","bend-or-outdoors"],"imageAsset":"assets/pacific/images/lake-tahoe-ca-lake/hero.jpg"},{"id":"portland-or-city","title":"Portland, OR: Three-Day City Adventure","destination":"Portland, OR","state":"OR","stateName":"Oregon","region":"Willamette Valley","days":3,"tripType":"city adventure","interests":["family","museums","food","nature"],"budget":1600,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, transit, and attraction tickets.","tagline":"Rose gardens, book towers, and the friendliest big city in the Pacific Northwest.","overview":"Portland is quirky in the best way \u2014 a city of food carts, rose gardens, and the world's biggest bookstore. Washington Park alone can fill a day with its zoo, Japanese garden, and playgrounds, and the Saturday Market's crafts keep kids browsing. Compact and easygoing, it's a low-stress city trip. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Get lost in four floors of Powell's City of Books","Walk the serene paths of the Portland Japanese Garden","Ride the zoo train and see elephants at the Oregon Zoo","Graze through the downtown food cart pods","Smell 10,000 roses at the International Rose Test Garden"],"bestSeason":"May\u2013September","familyFriendly":"Best for all ages. Compact downtown, great transit, and Washington Park's attractions are stroller-friendly.","lat":45.51179,"lng":-122.67563,"itinerary":[{"day":1,"title":"Washington Park","morning":{"stop":"Oregon Zoo","description":"Start at the zoo \u2014 the elephant lands, polar bears, and condors are highlights. The zoo railway gives tired legs a break with a scenic loop.","cost":"$24/adult, $19/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Portland Japanese Garden","description":"A short walk uphill to one of the finest Japanese gardens outside Japan. Kids get a scavenger-hunt map; the koi ponds and tea garden are peaceful wins.","cost":"$22/adult, $16/child (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Rose Garden & dinner","description":"Stroll the free International Rose Test Garden at golden hour \u2014 10,000 blooms with city views. Dinner in the Nob Hill/Alphabet District.","cost":"$50\u2013$75 for dinner (est.)","time":"4:30 PM \u2013 7:30 PM"}},{"day":2,"title":"Books & Science","morning":{"stop":"Powell's City of Books","description":"Give everyone an hour in the city-block bookstore \u2014 the kids' section and rare-book room are treasures. Grab coffee at the in-store caf\u00e9.","cost":"Free entry (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"OMSI","description":"The Oregon Museum of Science and Industry has a real submarine to tour (the USS Blueback), a planetarium, and hands-on labs. The submarine tour is the can't-miss.","cost":"$18/adult, $14/child (est.)","time":"1:00 PM \u2013 5:00 PM"},"evening":{"stop":"Food cart dinner","description":"Dinner from the downtown food cart pods \u2014 everyone picks their own cuisine. Dessert from Voodoo Doughnut or Blue Star.","cost":"$35\u2013$50 for dinner (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Markets & Waterfront","morning":{"stop":"Portland Saturday Market","description":"If it's the weekend, browse the country's largest weekly arts-and-crafts market under the Burnside Bridge. Street food and live music keep it lively.","cost":"Free entry (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Waterfront & lunch","description":"Walk the Tom McCall Waterfront Park along the Willamette. Lunch at Pine Street Market's food hall, then let the kids splash in the Salmon Street fountain.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Pittock Mansion sunset","description":"Drive up to Pittock Mansion for the classic Portland panorama \u2014 Mt. Hood on a clear day. Tour the 1914 mansion if time allows.","cost":"$13/adult, $8/child (est.)","time":"4:30 PM \u2013 7:00 PM"}}],"attractions":[{"name":"Oregon Zoo","description":"A 64-acre zoo in Washington Park known for its elephant breeding program, polar bears, and condors. The zoo railway and summer concerts make it a full-day family outing.","officialUrl":"https://www.oregonzoo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oregon+Zoo+Portland+OR","price":"$24/adult, $19/child (est.)","photos":["assets/pacific/images/portland-or-city/attr1-1.jpg","assets/pacific/images/portland-or-city/attr1-2.jpg","assets/pacific/images/portland-or-city/attr1-3.jpg","assets/pacific/images/portland-or-city/attr1-4.jpg"]},{"name":"Portland Japanese Garden","description":"Eight garden styles across 12 acres \u2014 strolling pond, tea garden, sand-and-stone \u2014 considered the most authentic outside Japan. Kids get an activity map; the Cultural Village hosts family workshops.","officialUrl":"https://www.japanesegarden.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Portland+Japanese+Garden+Portland+OR","price":"$22/adult, $16/child (est.)","photos":["assets/pacific/images/portland-or-city/attr2-1.jpg","assets/pacific/images/portland-or-city/attr2-2.jpg","assets/pacific/images/portland-or-city/attr2-3.jpg","assets/pacific/images/portland-or-city/attr2-4.jpg"]},{"name":"Powell's City of Books","description":"An entire city block of new and used books \u2014 over a million volumes. The kids' room, rare-book room, and author events make it a destination even for reluctant readers.","officialUrl":"https://www.powells.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Powell%27s+City+of+Books+Portland+OR","price":"Free entry (est.)","photos":["assets/pacific/images/portland-or-city/attr3-1.jpg","assets/pacific/images/portland-or-city/attr3-2.jpg","assets/pacific/images/portland-or-city/attr3-3.jpg","assets/pacific/images/portland-or-city/attr3-4.jpg"]},{"name":"Oregon Museum of Science and Industry","description":"OMSI's hands-on science halls, planetarium, and giant-screen theater anchor the east bank. The real USS Blueback submarine tour is the standout \u2014 book ahead.","officialUrl":"https://www.omsi.edu","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oregon+Museum+of+Science+and+Industry+Portland+OR","price":"$18/adult, $14/child (est.)","photos":["assets/pacific/images/portland-or-city/attr4-1.jpg","assets/pacific/images/portland-or-city/attr4-2.jpg","assets/pacific/images/portland-or-city/attr4-3.jpg","assets/pacific/images/portland-or-city/attr4-4.jpg"]}],"restaurants":[{"name":"Voodoo Doughnut","detail":"The famous pink-boxed doughnut shop \u2014 maple bars and the iconic voodoo doll, lines move fast.","price":"$"},{"name":"Screen Door","detail":"Southern comfort food in the Pearl \u2014 legendary fried chicken, worth the wait.","price":"$$"},{"name":"Deschutes Brewery Portland Public House","detail":"Bend-born brewery's Pearl District pub; great burgers and a kids' menu.","price":"$$"}],"rainyDay":["OMSI (all indoors)","Oregon Museum of Science submarine tour","Portland Children's Museum (Washington Park)"],"driveNotes":"Downtown Portland is walkable and the MAX light rail connects the airport, downtown, and Washington Park. Street parking downtown is metered; many hotels charge $30\u2013$45/night (est.). For the Gorge and coast, you'll want a car for a day.","related":["hood-river-or-scenic","cannon-beach-or-coast","bend-or-outdoors"],"imageAsset":"assets/pacific/images/portland-or-city/hero.jpg"},{"id":"cannon-beach-or-coast","title":"Cannon Beach, OR: Three-Day Coastal Escape","destination":"Cannon Beach, OR","state":"OR","stateName":"Oregon","region":"Oregon Coast","days":3,"tripType":"coastal escape","interests":["family","beaches","nature","scenic","food"],"budget":1500,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights coastal motel, meals, and attraction tickets.","tagline":"A 235-foot sea stack, tide pools full of starfish, and the coziest beach town on the Oregon coast.","overview":"Cannon Beach is the Oregon coast at its storybook best \u2014 Haystack Rock rising from the surf, puffins nesting in summer, and a walkable downtown of galleries and ice cream shops. Add Ecola State Park's headland trails and a cheese-factory detour, and three days feel perfectly paced. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["See puffins nesting on Haystack Rock (spring\u2013summer)","Explore tide pools at low tide around the rock","Hike Ecola State Park's headland viewpoints","Watch cheese being made at the Tillamook Creamery","Feed the seals at the Seaside Aquarium"],"bestSeason":"June\u2013September","familyFriendly":"Best for all ages. Beaches are wide and walkable; bring layers \u2014 the coast is 60\u00b0F even in July.","lat":45.89047,"lng":-123.96181,"itinerary":[{"day":1,"title":"Haystack Rock","morning":{"stop":"Haystack Rock & tide pools","description":"Time your visit for low tide and walk out to the 235-foot sea stack. Volunteer naturalists point out starfish, anemones, and nesting puffins (April\u2013August). Kids can spend hours in the tide pools.","cost":"Free (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Downtown Cannon Beach","description":"Lunch downtown, then browse the galleries and candy shops. The Cannon Beach History Center is a quick, fun stop for the Lewis & Clark story.","cost":"$45\u2013$65 for lunch (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Beach bonfire evening","description":"Many beachfront inns provide bonfire kits \u2014 s'mores on the sand as the sun sets behind Haystack Rock. Pure Oregon coast magic.","cost":"$20 s'mores supplies (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Headlands & Creamery","morning":{"stop":"Ecola State Park","description":"Hike the 2.5-mile Clatsop Loop or just hit the Ecola Point viewpoint for the classic headland-and-sea-stack panorama. Old-growth Sitka spruce towers over the trail.","cost":"$5 day use (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Tillamook Creamery","description":"Drive 45 minutes south to watch cheddar being made through the viewing windows, then the essential stop: the ice cream counter. The self-guided tour is free and kid-friendly.","cost":"Free tour; ice cream $6\u2013$9 (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner in Cannon Beach","description":"Back in town for dinner \u2014 seafood chowder and fish and chips are the move. Evening stroll on the beach if energy remains.","cost":"$55\u2013$80 for dinner (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Seaside & Farewell","morning":{"stop":"Seaside Aquarium","description":"Drive 15 minutes north to one of America's oldest aquariums. Kids feed the harbor seals \u2014 the highlight \u2014 and touch tanks hold starfish and urchins.","cost":"$12/adult, $7/child (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Seaside beach & lunch","description":"Lunch on Broadway, then play on Seaside's wide beach \u2014 fly kites, ride the carousel mall's amusements, or just dig in the sand.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell sunset","description":"Return to Cannon Beach for one last Haystack Rock sunset. Grab saltwater taffy for the road.","cost":"$15 souvenirs (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Haystack Rock","description":"The 235-foot basalt sea stack is an Oregon icon \u2014 and a protected marine garden. At low tide, walk right up to tide pools full of starfish and anemones; in spring and summer, tufted puffins nest on its ledges.","officialUrl":"https://www.cannonbeach.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Haystack+Rock+Cannon+Beach+OR","price":"Free (est.)","photos":["assets/pacific/images/cannon-beach-or-coast/attr1-1.jpg","assets/pacific/images/cannon-beach-or-coast/attr1-2.jpg","assets/pacific/images/cannon-beach-or-coast/attr1-3.jpg","assets/pacific/images/cannon-beach-or-coast/attr1-4.jpg"]},{"name":"Ecola State Park","description":"Headland trails through old-growth spruce with sweeping views of sea stacks and hidden coves. The Ecola Point viewpoint and the Clatsop Loop trail are the family-friendly highlights.","officialUrl":"https://stateparks.oregon.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Ecola+State+Park+Cannon+Beach+OR","price":"$5 day use (est.)","photos":["assets/pacific/images/cannon-beach-or-coast/attr2-1.jpg","assets/pacific/images/cannon-beach-or-coast/attr2-2.jpg","assets/pacific/images/cannon-beach-or-coast/attr2-3.jpg","assets/pacific/images/cannon-beach-or-coast/attr2-4.jpg"]},{"name":"Tillamook Creamery","description":"Watch cheddar being made, learn the dairy story on the free self-guided tour, and \u2014 critically \u2014 eat the ice cream. A 45-minute drive south and worth every minute.","officialUrl":"https://www.tillamook.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tillamook+Creamery+Tillamook+OR","price":"Free tour (est.)","photos":["assets/pacific/images/cannon-beach-or-coast/attr3-1.jpg","assets/pacific/images/cannon-beach-or-coast/attr3-2.jpg","assets/pacific/images/cannon-beach-or-coast/attr3-3.jpg","assets/pacific/images/cannon-beach-or-coast/attr3-4.jpg"]},{"name":"Seaside Aquarium","description":"Feeding the barking harbor seals is the star attraction at this 1937 oceanfront aquarium. Touch tanks, a shark exhibit, and the skeletal remains of a 35-foot gray whale round it out.","officialUrl":"https://www.seasideaquarium.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Seaside+Aquarium+Seaside+OR","price":"$12/adult, $7/child (est.)","photos":["assets/pacific/images/cannon-beach-or-coast/attr4-1.jpg","assets/pacific/images/cannon-beach-or-coast/attr4-2.jpg","assets/pacific/images/cannon-beach-or-coast/attr4-3.jpg","assets/pacific/images/cannon-beach-or-coast/attr4-4.jpg"]}],"restaurants":[{"name":"Mo's Seafood & Chowder","detail":"Oregon coast institution \u2014 the clam chowder is famous and the kids' menu is solid.","price":"$"},{"name":"Driftwood Restaurant & Lounge","detail":"Classic Cannon Beach spot with ocean views and prime rib weekends.","price":"$$"},{"name":"Ecola Seafood Restaurant & Market","detail":"Counter-service fish market with the freshest catch sandwiches in town.","price":"$"}],"rainyDay":["Cannon Beach History Center & Museum","Seaside Aquarium (indoors)","Tillamook Creamery (indoors)"],"driveNotes":"Highway 101 is scenic but slow \u2014 allow extra time between towns. Cannon Beach is 90 minutes from Portland via Highway 26. Summer weekends book out months ahead; fog and 60\u00b0F weather are normal even in August, so pack layers.","related":["portland-or-city","hood-river-or-scenic","san-juan-wa-islands"],"imageAsset":"assets/pacific/images/cannon-beach-or-coast/hero.jpg"},{"id":"bend-or-outdoors","title":"Bend, OR: Three-Day Outdoor Adventure","destination":"Bend, OR","state":"OR","stateName":"Oregon","region":"Central Oregon","days":3,"tripType":"outdoor adventure","interests":["family","outdoors","nature","scenic","food"],"budget":1500,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, and attraction tickets.","tagline":"Desert sun, river floats, lava caves, and a mountain town that runs on adventure.","overview":"Bend sits where the Cascades meet the high desert \u2014 300 days of sunshine and adventure in every direction. Float the Deschutes River through town, walk among otters and raptors at the High Desert Museum, and stand on a lava flow at Newberry Volcano. It's the rare mountain town that's as easy as it is epic. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Float the Deschutes River through downtown Bend","Meet river otters and raptors at the High Desert Museum","Climb the Misery Ridge trail at Smith Rock","Walk a lava tube at Newberry Volcano","Watch climbers on Smith Rock's 650-foot walls"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 6+. River floating suits confident swimmers with life jackets; the museum and lava lands are great for all ages.","lat":44.05782,"lng":-121.31537,"itinerary":[{"day":1,"title":"River Day","morning":{"stop":"Deschutes River float","description":"Rent tubes and float the 2-mile park stretch through town \u2014 rapids are gentle and there's a whitewater park to watch kayakers. Life jackets required for kids.","cost":"Tube rental ~$20/person (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Downtown Bend lunch","description":"Dry off and lunch downtown \u2014 food carts, pizza, and ice cream everywhere. Browse the outdoor shops on Wall Street.","cost":"$45\u2013$65 for lunch (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Drake Park evening","description":"Picnic or playground time at Drake Park along the river. Summer evenings often have free concerts at the amphitheater.","cost":"$30\u2013$45 picnic (est.)","time":"5:00 PM \u2013 7:30 PM"}},{"day":2,"title":"Museum & Volcano","morning":{"stop":"High Desert Museum","description":"River otters, porcupines, and raptor shows \u2014 plus a recreated 1904 homestead and sawmill. The otter exhibit alone is worth the trip.","cost":"$23/adult, $14/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Newberry Volcano: Lava Lands","description":"Drive to the Lava Lands Visitor Center and walk the Trail of the Molten Land across a 7,000-year-old lava flow. Ride the shuttle (summer) up Lava Butte for Cascade views.","cost":"$5/vehicle (est.)","time":"2:00 PM \u2013 5:30 PM"},"evening":{"stop":"Dinner & downtown","description":"Back to Bend for dinner \u2014 the brewery scene is family-friendly until evening. Stroll the Deschutes riverfront at sunset.","cost":"$55\u2013$80 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":3,"title":"Smith Rock","morning":{"stop":"Smith Rock State Park","description":"A 40-minute drive to the birthplace of American sport climbing. Hike the easy Misery Ridge loop (3.7 miles) or just the river trail for jaw-dropping 650-foot walls \u2014 and watch climbers dangle.","cost":"$5 day use (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Tumalo Falls","description":"On the way back, stop at Tumalo Falls \u2014 a 97-foot cascade a short walk from the parking area. Easy, gorgeous, done in an hour.","cost":"Free (est.)","time":"2:00 PM \u2013 3:30 PM"},"evening":{"stop":"Farewell dinner","description":"Final dinner in Bend \u2014 pizza or barbecue, then ice cream on the river. Pack for an easy morning departure.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Smith Rock State Park","description":"Towering 650-foot tuff and basalt cliffs above the Crooked River \u2014 the birthplace of American sport climbing. The Misery Ridge loop and river trails deliver big views; bring binoculars for climbers and golden eagles.","officialUrl":"https://stateparks.oregon.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Smith+Rock+State+Park+Terrebonne+OR","price":"$5 day use (est.)","photos":["assets/pacific/images/bend-or-outdoors/attr1-1.jpg","assets/pacific/images/bend-or-outdoors/attr1-2.jpg","assets/pacific/images/bend-or-outdoors/attr1-3.jpg","assets/pacific/images/bend-or-outdoors/attr1-4.jpg"]},{"name":"High Desert Museum","description":"Wildlife encounters \u2014 river otters, bobcats, raptors \u2014 plus living-history exhibits of homesteaders and Native cultures. The daily raptor flight show is unforgettable.","officialUrl":"https://www.highdesertmuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=High+Desert+Museum+Bend+OR","price":"$23/adult, $14/child (est.)","photos":["assets/pacific/images/bend-or-outdoors/attr2-1.jpg","assets/pacific/images/bend-or-outdoors/attr2-2.jpg","assets/pacific/images/bend-or-outdoors/attr2-3.jpg","assets/pacific/images/bend-or-outdoors/attr2-4.jpg"]},{"name":"Deschutes River Trail","description":"Miles of paved riverside path through Bend, plus the famous float stretch with gentle rapids and the Bend Whitewater Park. Rent tubes, kayaks, or paddleboards all along the river.","officialUrl":"https://www.bendparksandrec.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Deschutes+River+Trail+Bend+OR","price":"Free; rentals ~$20 (est.)","photos":["assets/pacific/images/bend-or-outdoors/attr3-1.jpg","assets/pacific/images/bend-or-outdoors/attr3-2.jpg","assets/pacific/images/bend-or-outdoors/attr3-3.jpg","assets/pacific/images/bend-or-outdoors/attr3-4.jpg"]},{"name":"Newberry National Volcanic Monument","description":"A massive shield volcano with lava flows, cinder cones, and two alpine lakes. Walk the Trail of the Molten Land and take the summer shuttle up Lava Butte for 360-degree Cascade views.","officialUrl":"https://www.fs.usda.gov/recarea/deschutes/recarea/?recid=66167","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Newberry+National+Volcanic+Monument+Bend+OR","price":"$5/vehicle (est.)","photos":["assets/pacific/images/bend-or-outdoors/attr4-1.jpg","assets/pacific/images/bend-or-outdoors/attr4-2.jpg","assets/pacific/images/bend-or-outdoors/attr4-3.jpg","assets/pacific/images/bend-or-outdoors/attr4-4.jpg"]}],"restaurants":[{"name":"Deschutes Brewery","detail":"The downtown pub that started it all \u2014 great burgers, kids' menu, family-friendly.","price":"$$"},{"name":"Pine Tavern","detail":"Bend classic since 1936 on the river \u2014 famous for the pine tree growing through the dining room.","price":"$$"},{"name":"Spork","detail":"Global street food in a funky space \u2014 Korean tacos and bao buns kids love.","price":"$"}],"rainyDay":["High Desert Museum (mostly indoors)","Bend Rock Gym (kids' climbing)","The Workhouse (craft workshops)"],"driveNotes":"Bend is 3 hours from Portland over the Cascades \u2014 check pass conditions in shoulder seasons. Summer books out; book lodging early. The town is bike-friendly and compact, but you'll want a car for Smith Rock and Newberry.","related":["crater-lake-or-nature","hood-river-or-scenic","portland-or-city"],"imageAsset":"assets/pacific/images/bend-or-outdoors/hero.jpg"},{"id":"crater-lake-or-nature","title":"Crater Lake, OR: Two-Day Nature Escape","destination":"Crater Lake, OR","state":"OR","stateName":"Oregon","region":"Southern Oregon","days":2,"tripType":"nature escape","interests":["family","outdoors","nature","scenic"],"budget":800,"budgetNote":"Est. for 2 adults + 2 kids: 1 night in-park lodge or nearby motel, meals, park entry, and boat tour.","tagline":"The bluest lake in America, born from a volcano's collapse 7,700 years ago.","overview":"Crater Lake's impossible blue \u2014 1,949 feet deep, fed only by snow \u2014 has to be seen to be believed. Two days covers the rim drive's best viewpoints, a hike down to the water's edge, and maybe the boat ride to Wizard Island. It's remote, so come prepared \u2014 and go in summer, when the rim road is fully open. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["See the impossibly blue 1,949-foot-deep lake","Boat to Wizard Island's volcanic cinder cone","Hike down to the water at Cleetwood Cove","Watch sunset from Watchman Overlook","Spot the Old Man of the Lake's floating log"],"bestSeason":"July\u2013September","familyFriendly":"Best for ages 6+. Rim viewpoints are easy; the Cleetwood hike down is steep (1.1 miles, 700 ft) \u2014 strong legs only.","lat":42.91138,"lng":-122.14763,"itinerary":[{"day":1,"title":"The Rim","morning":{"stop":"Rim Village & Sinnott Memorial","description":"Start at Rim Village for the first jaw-drop view, then walk the indoor Rim Trail exhibits at the Sinnott Overlook. The Junior Ranger program starts at the visitor center.","cost":"$30/vehicle park entry (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Rim Drive east","description":"Drive the 33-mile Rim Drive clockwise, stopping at Discovery Point, the Pinnacles, and Cloudcap Overlook \u2014 the highest paved viewpoint. Picnic lunch at a pullout with the lake below.","cost":"$30\u2013$45 picnic supplies (est.)","time":"1:30 PM \u2013 5:30 PM"},"evening":{"stop":"Sunset at Watchman","description":"End at Watchman Overlook for sunset \u2014 Wizard Island silhouetted against orange water. Dinner at the Rim Village caf\u00e9 or the lodge dining room.","cost":"$50\u2013$75 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Down to the Water","morning":{"stop":"Cleetwood Cove Trail","description":"The only trail to the lake's shore \u2014 a steep 1.1-mile descent (700 feet) to impossibly clear water. Kids love touching the 38\u00b0F water; strong hikers only for the climb back.","cost":"Free (est.)","time":"9:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Wizard Island boat tour","description":"From Cleetwood Cove, the boat tour circles the lake and stops at Wizard Island \u2014 hike to the top of the cinder cone for the classic crater-within-a-crater view. Book ahead; tours sell out.","cost":"$44/adult, $30/child (est.)","time":"12:30 PM \u2013 4:00 PM"},"evening":{"stop":"Pinnacles & departure","description":"On the way out, stop at the Pinnacles Overlook \u2014 eerie volcanic spires in a canyon. Grab dinner in Fort Klamath or Chemult on the drive.","cost":"$35\u2013$55 for dinner (est.)","time":"4:30 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Rim Drive","description":"The 33-mile scenic road circling the caldera with 30+ overlooks. Discovery Point, Cloudcap, and Phantom Ship viewpoints each show a different face of the blue lake. Fully open only July\u2013September.","officialUrl":"https://www.nps.gov/crla","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rim+Drive+Crater+Lake+OR","price":"$30/vehicle entry (est.)","photos":["assets/pacific/images/crater-lake-or-nature/attr1-1.jpg","assets/pacific/images/crater-lake-or-nature/attr1-2.jpg","assets/pacific/images/crater-lake-or-nature/attr1-3.jpg","assets/pacific/images/crater-lake-or-nature/attr1-4.jpg"]},{"name":"Wizard Island","description":"A cinder cone rising 760 feet from the lake \u2014 a volcano inside a volcano. Reach it by the summer boat tour, then hike the 0.9-mile trail to the top for the Fumarole Bay view.","officialUrl":"https://www.nps.gov/crla","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wizard+Island+Crater+Lake+OR","price":"Boat tour $44/adult, $30/child (est.)","photos":["assets/pacific/images/crater-lake-or-nature/attr2-1.jpg","assets/pacific/images/crater-lake-or-nature/attr2-2.jpg","assets/pacific/images/crater-lake-or-nature/attr2-3.jpg","assets/pacific/images/crater-lake-or-nature/attr2-4.jpg"]},{"name":"Cleetwood Cove Trail","description":"The only legal route to the water's edge: a steep 2.2-mile round trip dropping 700 feet to the shore. Touch the famously cold, clear water and watch trout swim 100 feet down.","officialUrl":"https://www.nps.gov/crla","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cleetwood+Cove+Trail+Crater+Lake+OR","price":"Included with entry (est.)","photos":["assets/pacific/images/crater-lake-or-nature/attr3-1.jpg","assets/pacific/images/crater-lake-or-nature/attr3-2.jpg","assets/pacific/images/crater-lake-or-nature/attr3-3.jpg","assets/pacific/images/crater-lake-or-nature/attr3-4.jpg"]},{"name":"Pinnacles Overlook","description":"A short walk to fossil fumaroles \u2014 spires of hardened volcanic gas vents \u2014 in Wheeler Canyon. It feels like another planet and takes under an hour.","officialUrl":"https://www.nps.gov/crla","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pinnacles+Overlook+Crater+Lake+OR","price":"Included with entry (est.)","photos":["assets/pacific/images/crater-lake-or-nature/attr4-1.jpg","assets/pacific/images/crater-lake-or-nature/attr4-2.jpg","assets/pacific/images/crater-lake-or-nature/attr4-3.jpg","assets/pacific/images/crater-lake-or-nature/attr4-4.jpg"]}],"restaurants":[{"name":"Crater Lake Lodge Dining Room","detail":"The grand 1915 lodge's restaurant \u2014 lake views and the park's best sit-down meal.","price":"$$$"},{"name":"Annie Creek Restaurant","detail":"Casual cafeteria at Mazama Village with burgers, pizza, and grab-and-go.","price":"$"},{"name":"Rim Village Caf\u00e9","detail":"Quick soups, sandwiches, and ice cream right on the rim \u2014 perfect lunch stop.","price":"$"}],"rainyDay":["Sinnott Memorial Overlook exhibits (indoors)","Steel Visitor Center film & exhibits","Crater Lake Lodge great hall (lobby games & views)"],"driveNotes":"Crater Lake is remote \u2014 the nearest real town is 45+ minutes away, so fill the tank and pack food. The full Rim Drive and boat tours run only in summer (roughly July\u2013September); snow can linger into July. Lodging in the park books out a year ahead.","related":["bend-or-outdoors","mount-rainier-wa-nature","olympic-wa-nature"],"imageAsset":"assets/pacific/images/crater-lake-or-nature/hero.jpg"},{"id":"hood-river-or-scenic","title":"Hood River, OR: Three-Day Scenic Getaway","destination":"Hood River, OR","state":"OR","stateName":"Oregon","region":"Columbia River Gorge","days":3,"tripType":"scenic getaway","interests":["family","outdoors","nature","scenic","food"],"budget":1400,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, and attraction tickets.","tagline":"Waterfalls around every bend, a snowcapped volcano on the horizon, and the windsurfing capital of the world.","overview":"The Columbia River Gorge packs more waterfalls per mile than anywhere in America, and Hood River sits at its heart. Chase Multnomah and Latourell Falls along the historic highway, ride up to Timberline Lodge on Mt. Hood, and watch windsurfers dance on the river at sunset. Three days of pure Pacific Northwest wow. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Stand in the mist at the base of Multnomah Falls","Tour the great stone Timberline Lodge on Mt. Hood","Watch windsurfers at the Hood River waterfront","Drive the waterfall-lined Historic Columbia River Highway","Pick fruit on the Hood River Fruit Loop"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 5+. Waterfall trails are short and paved; bring rain jackets for the falls' mist.","lat":45.70886,"lng":-121.51073,"itinerary":[{"day":1,"title":"Waterfall Highway","morning":{"stop":"Multnomah Falls","description":"Arrive by 9 AM for parking at Oregon's tallest waterfall (620 feet). Walk to Benson Bridge for the classic photo, then climb to the top viewpoint if legs allow (2.4 miles round trip). Timed entry permits required in summer.","cost":"Free; timed permit $2 (est.)","time":"9:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Historic Highway waterfalls","description":"Drive the old highway west to Latourell Falls (punchbowl plunge pool, easy loop), Bridal Veil, and Wahkeena. Each is a short walk \u2014 waterfall-hop at your own pace.","cost":"Free (est.)","time":"12:30 PM \u2013 4:30 PM"},"evening":{"stop":"Hood River waterfront","description":"Dinner in Hood River, then walk the waterfront park at sunset. Watch windsurfers and kiteboarders carve the famous gorge winds.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Mt. Hood","morning":{"stop":"Timberline Lodge","description":"Drive 45 minutes up to the 1936 WPA lodge at 6,000 feet \u2014 massive timbers, a 92-foot stone chimney, and year-round snow outside. Tour the head-house, ride the Magic Mile chairlift in summer.","cost":"Free entry; lift $25\u2013$35 (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Alpine slides & lunch","description":"Summer brings the alpine slide and mountain biking at the Ski Bowl nearby. Lunch at the lodge's casual Ram's Head Bar with mountain views.","cost":"$45\u2013$65 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Fruit Loop drive","description":"Wind back down through the Hood River Valley's Fruit Loop \u2014 farm stands, cherry orchards, and lavender fields. Pick your own fruit in season and grab pie for dessert.","cost":"$20\u2013$40 for fruit & pie (est.)","time":"4:30 PM \u2013 7:00 PM"}},{"day":3,"title":"River & Farewell","morning":{"stop":"Hood River waterfront park","description":"Morning at the waterfront \u2014 swim beach, playground, and the best windsurfing spectating on earth. Rent stand-up paddleboards if the kids are adventurous.","cost":"SUP rental ~$25/hr (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Downtown & lunch","description":"Lunch downtown, then browse the shops and the Columbia Center for Urban Agriculture's farm stand. The History Museum of Hood River County is a quick fun stop.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Panorama Point sunset","description":"Drive up to Panorama Point for the classic Mt. Hood-over-orchards sunset. Farewell dinner back in town.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Multnomah Falls","description":"Oregon's tallest waterfall at 620 feet, plunging past the storybook Benson Bridge. The paved walk to the bridge is easy; the 2.4-mile climb to the top is for energetic families. Summer visits need a timed entry permit.","officialUrl":"https://www.fs.usda.gov/recarea/crgnsa/recarea/?recid=79476","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Multnomah+Falls+Bridal+Veil+OR","price":"Free; permit $2 (est.)","photos":["assets/pacific/images/hood-river-or-scenic/attr1-1.jpg","assets/pacific/images/hood-river-or-scenic/attr1-2.jpg","assets/pacific/images/hood-river-or-scenic/attr1-3.jpg","assets/pacific/images/hood-river-or-scenic/attr1-4.jpg"]},{"name":"Timberline Lodge","description":"The grand 1936 mountain lodge built by the WPA, sitting at 6,000 feet on Mt. Hood. Tour the great hall's carved wood and ironwork, ride the summer chairlift, and touch snow in July.","officialUrl":"https://www.timberlinelodge.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Timberline+Lodge+Government+Camp+OR","price":"Free entry (est.)","photos":["assets/pacific/images/hood-river-or-scenic/attr2-1.jpg","assets/pacific/images/hood-river-or-scenic/attr2-2.jpg","assets/pacific/images/hood-river-or-scenic/attr2-3.jpg","assets/pacific/images/hood-river-or-scenic/attr2-4.jpg"]},{"name":"Hood River Waterfront Park","description":"The windsurfing capital's front porch: swim beach, playground, event lawn, and front-row seats to hundreds of windsurfers and kiteboarders. Sunset here is a daily show.","officialUrl":"https://www.portofhoodriver.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hood+River+Waterfront+Park+Hood+River+OR","price":"Free (est.)","photos":["assets/pacific/images/hood-river-or-scenic/attr3-1.jpg","assets/pacific/images/hood-river-or-scenic/attr3-2.jpg","assets/pacific/images/hood-river-or-scenic/attr3-3.jpg","assets/pacific/images/hood-river-or-scenic/attr3-4.jpg"]},{"name":"Latourell Falls","description":"A 249-foot plunge into a punchbowl pool, reached by an easy 2.4-mile loop through mossy basalt columns. The lower viewpoint alone \u2014 five minutes from the parking lot \u2014 is stunning.","officialUrl":"https://www.fs.usda.gov/recarea/crgnsa/recarea/?recid=79476","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Latourell+Falls+Corbett+OR","price":"Free (est.)","photos":["assets/pacific/images/hood-river-or-scenic/attr4-1.jpg","assets/pacific/images/hood-river-or-scenic/attr4-2.jpg","assets/pacific/images/hood-river-or-scenic/attr4-3.jpg","assets/pacific/images/hood-river-or-scenic/attr4-4.jpg"]}],"restaurants":[{"name":"pFriem Family Brewers","detail":"Waterfront brewery with Belgian-style beers and a great kids' menu \u2014 the family-friendly tasting room.","price":"$$"},{"name":"Solstice Wood Fire Pizza Caf\u00e9","detail":"Wood-fired pizzas and local ingredients in a cozy downtown spot.","price":"$$"},{"name":"Double Mountain Brewery","detail":"Brick-oven pizza and house-brewed root beer \u2014 loud, fun, kid-approved.","price":"$"}],"rainyDay":["Columbia Gorge Discovery Center (The Dalles)","Hood River History Museum","Timberline Lodge (tour the great hall)"],"driveNotes":"Hood River is 60\u201390 minutes east of Portland on I-84 \u2014 an easy day trip, but stay over for the full experience. The Historic Columbia River Highway is slow and winding; allow double the time you think. Summer weekends at Multnomah Falls require timed entry permits booked ahead.","related":["portland-or-city","bend-or-outdoors","cannon-beach-or-coast"],"imageAsset":"assets/pacific/images/hood-river-or-scenic/hero.jpg"},{"id":"seattle-wa-city","title":"Seattle, WA: Four-Day City Adventure","destination":"Seattle, WA","state":"WA","stateName":"Washington","region":"Puget Sound","days":4,"tripType":"city adventure","interests":["family","museums","food","scenic"],"budget":2400,"budgetNote":"Est. for 2 adults + 2 kids: 3 nights mid-range hotel, meals, transit, and attraction tickets.","tagline":"A needle in the sky, fish that fly, and glass flowers that never wilt.","overview":"Seattle is a city of icons that actually live up to the hype. The Space Needle's revolving glass floor, Pike Place's flying fish, and Chihuly's glowing glass garden fill days easily \u2014 and the waterfront aquarium and pop-culture museum keep every age engaged. Four days lets you savor it without rushing. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Stand on the Space Needle's revolving glass floor","Watch fish fly at Pike Place Market","Walk through Chihuly's glowing glass garden","Touch sea stars at the Seattle Aquarium","Tour pop culture at MoPOP's music exhibits"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 5+. Seattle Center's attractions cluster together and are stroller-friendly; hills downtown are steep.","lat":47.60357,"lng":-122.32945,"itinerary":[{"day":1,"title":"Seattle Center Icons","morning":{"stop":"Space Needle","description":"Ride to the top for 360-degree views \u2014 the revolving glass floor on the lower level is the thrill. Go early for the shortest lines and clearest views of Mt. Rainier.","cost":"$37/adult, $28/child (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Chihuly Garden and Glass","description":"Right next door: eight galleries and a garden of Dale Chihuly's monumental glass sculptures. Kids are mesmerized by the 100-foot suspended sculpture and the glasshouse.","cost":"$36/adult, $22/child (est.)","time":"12:30 PM \u2013 2:30 PM"},"evening":{"stop":"MoPOP","description":"The Museum of Pop Culture's music, sci-fi, and gaming exhibits \u2014 including a hands-on sound lab where kids play real instruments. Dinner at the Armory food hall.","cost":"$32/adult, $22/child (est.)","time":"3:00 PM \u2013 6:30 PM"}},{"day":2,"title":"Market & Waterfront","morning":{"stop":"Pike Place Market","description":"Watch the fish throwers, meet Rachel the pig, and graze the stalls \u2014 mini donuts, fresh fruit, and the original Starbucks line. The Gum Wall (Post Alley) is gross and kids love it.","cost":"Free; grazing $30\u2013$50 (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Seattle Aquarium","description":"Walk down to the waterfront aquarium: touch sea stars and urchins, watch river otters play, and see the giant Pacific octopus. The underwater dome is the finale.","cost":"$36/adult, $26/child (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Waterfront dinner","description":"Dinner on the waterfront \u2014 clam chowder with Elliott Bay views. Ride the Great Wheel for a sunset spin over the water.","cost":"Wheel $18/adult, $13/child (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":3,"title":"Boats & Ballard","morning":{"stop":"Argosy harbor cruise","description":"A one-hour narrated cruise past the skyline, houseboats, and working waterfront. Kids get a front-row seat to ferries and container ships.","cost":"$35/adult, $17/child (est.)","time":"10:00 AM \u2013 11:30 AM"},"afternoon":{"stop":"Ballard Locks & lunch","description":"Watch boats \u2014 and leaping salmon in season \u2014 rise and fall in the locks. The fish ladder viewing room is fascinating. Lunch in Ballard's cute downtown.","cost":"$45\u2013$65 for lunch (est.)","time":"12:00 PM \u2013 3:30 PM"},"evening":{"stop":"Kerry Park sunset","description":"The classic postcard viewpoint: skyline, Space Needle, and Mt. Rainier in one frame. Dinner in Queen Anne on the way back.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":4,"title":"Museums & Farewell","morning":{"stop":"Museum of Flight","description":"A 20-minute drive south to one of the world's great air museums \u2014 walk through a Concorde, an Air Force One, and the original Boeing factory. Kids can climb into cockpits.","cost":"$28/adult, $19/child (est.)","time":"10:00 AM \u2013 1:30 PM"},"afternoon":{"stop":"Fremont & lunch","description":"Lunch in funky Fremont, then photos with the Fremont Troll under the bridge. The Theo Chocolate factory tour (book ahead) is a sweet stop.","cost":"Chocolate tour $16/person (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"Farewell at Gas Works","description":"End at Gas Works Park \u2014 kite flying on the hill with the skyline behind you. Grab takeout for a sunset picnic.","cost":"$35\u2013$50 takeout (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Space Needle","description":"Seattle's 605-foot icon with a 360-degree observation deck and the world's first revolving glass floor. The 41-second elevator ride and the views \u2014 from Puget Sound to Mt. Rainier \u2014 are unforgettable.","officialUrl":"https://www.spaceneedle.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Space+Needle+Seattle+WA","price":"$37/adult, $28/child (est.)","photos":["assets/pacific/images/seattle-wa-city/attr1-1.jpg","assets/pacific/images/seattle-wa-city/attr1-2.jpg","assets/pacific/images/seattle-wa-city/attr1-3.jpg","assets/pacific/images/seattle-wa-city/attr1-4.jpg"]},{"name":"Pike Place Market","description":"The 1907 farmers market where fish fly through the air and flower bouquets cost $10. Meet Rachel the bronze pig, explore the lower levels' odd shops, and don't skip the Gum Wall.","officialUrl":"https://www.pikeplacemarket.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pike+Place+Market+Seattle+WA","price":"Free entry (est.)","photos":["assets/pacific/images/seattle-wa-city/attr2-1.jpg","assets/pacific/images/seattle-wa-city/attr2-2.jpg","assets/pacific/images/seattle-wa-city/attr2-3.jpg","assets/pacific/images/seattle-wa-city/attr2-4.jpg"]},{"name":"Seattle Aquarium","description":"On the waterfront: Pacific Northwest marine life from sea otters to giant Pacific octopus, plus touch pools with sea stars and anemones. The underwater dome puts you inside the exhibit.","officialUrl":"https://www.seattleaquarium.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Seattle+Aquarium+Seattle+WA","price":"$36/adult, $26/child (est.)","photos":["assets/pacific/images/seattle-wa-city/attr3-1.jpg","assets/pacific/images/seattle-wa-city/attr3-2.jpg","assets/pacific/images/seattle-wa-city/attr3-3.jpg","assets/pacific/images/seattle-wa-city/attr3-4.jpg"]},{"name":"Chihuly Garden and Glass","description":"Dale Chihuly's luminous glass sculptures in eight galleries and a garden, crowned by a 100-foot-long suspended installation. The glasshouse with the Space Needle behind it is pure magic.","officialUrl":"https://www.chihulygardenandglass.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chihuly+Garden+and+Glass+Seattle+WA","price":"$36/adult, $22/child (est.)","photos":["assets/pacific/images/seattle-wa-city/attr4-1.jpg","assets/pacific/images/seattle-wa-city/attr4-2.jpg","assets/pacific/images/seattle-wa-city/attr4-3.jpg","assets/pacific/images/seattle-wa-city/attr4-4.jpg"]}],"restaurants":[{"name":"Pike Place Chowder","detail":"Award-winning clam chowder in the market \u2014 the line moves fast and it's worth it.","price":"$"},{"name":"Ivar's Acres of Clams","detail":"Waterfront seafood institution since 1938; the kids' menu and fish bar deliver.","price":"$$"},{"name":"The Crab Pot","detail":"Seawall-side spot famous for dumping buckets of crab and shrimp on the table.","price":"$$"}],"rainyDay":["MoPOP (all indoors)","Seattle Aquarium (all indoors)","Museum of Flight (all indoors)"],"driveNotes":"Downtown Seattle is walkable but hilly \u2014 use the monorail between downtown and Seattle Center. Parking downtown runs $30\u2013$50/day (est.). For Ballard and the Museum of Flight, a car or rideshare is easiest.","related":["olympic-wa-nature","mount-rainier-wa-nature","san-juan-wa-islands"],"imageAsset":"assets/pacific/images/seattle-wa-city/hero.jpg"},{"id":"olympic-wa-nature","title":"Olympic National Park, WA: Three-Day Nature Escape","destination":"Olympic National Park, WA","state":"WA","stateName":"Washington","region":"Olympic Peninsula","days":3,"tripType":"nature escape","interests":["family","outdoors","nature","scenic","beaches"],"budget":1400,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights lodge or motel, meals, park entry, and gas.","tagline":"Rainforest, alpine peaks, and wild beaches \u2014 three national parks' worth of wonder in one.","overview":"Olympic is three parks in one: moss-draped rainforest, jagged alpine ridges, and driftwood-strewn Pacific beaches. Base in Port Angeles and each day explores a different world \u2014 Hurricane Ridge's mountain views, the Hoh's cathedral of green, and Rialto Beach's sea stacks. Few parks reward families this richly. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk through the mossy cathedral of the Hoh Rain Forest","See the Strait of Juan de Fuca from Hurricane Ridge","Explore tide pools at Rialto Beach's Hole-in-the-Wall","Kayak the crystal waters of Lake Crescent","Spot Roosevelt elk in the Hoh valley"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 6+. Hoh's Hall of Mosses trail is flat and stroller-friendly; Hurricane Ridge has easy paved viewpoints.","lat":48.09974,"lng":-123.42521,"itinerary":[{"day":1,"title":"Hurricane Ridge","morning":{"stop":"Hurricane Ridge","description":"Drive the 45-minute mountain road from Port Angeles to 5,242 feet. Paved trails lead to jaw-dropping views of the Olympics and the strait \u2014 look for marmots and deer right by the parking lot.","cost":"$30/vehicle park entry (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Visitor center & picnic","description":"Lunch at the ridge picnic area, then the visitor center's exhibits and film. The short Sunrise Point trail is an easy add-on.","cost":"$30\u2013$45 picnic supplies (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Port Angeles waterfront","description":"Back down for dinner on the Port Angeles waterfront. The kids can watch the Coho ferry sail for Victoria across the strait.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Hoh Rain Forest","morning":{"stop":"Hall of Mosses","description":"The 90-minute drive to the Hoh is part of the adventure. Walk the 0.8-mile Hall of Mosses loop \u2014 bigleaf maples draped in clubmoss, Roosevelt elk grazing, pure storybook.","cost":"Included with entry (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Spruce Nature Trail","description":"The 1.2-mile Spruce Nature Trail follows the Hoh River through 500-year-old spruce. Picnic at the rain forest picnic area \u2014 it rains 12+ feet a year here, so bring jackets.","cost":"$30\u2013$45 picnic supplies (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Ruby Beach sunset","description":"Drive to Ruby Beach for sunset \u2014 sea stacks, driftwood, and crashing surf. One of the most photographed beaches in America.","cost":"Free (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Beaches & Lake","morning":{"stop":"Rialto Beach","description":"Walk the beach to Hole-in-the-Wall (1.5 miles each way at low tide) \u2014 tide pools, sea stacks, and bald eagles. Check tide tables; go at low tide.","cost":"Included with entry (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Lake Crescent","description":"Drive to Lake Crescent's impossibly clear blue water. Swim at East Beach, walk the 1-mile Moments in Time trail, or rent kayaks at the lodge.","cost":"Kayak rental ~$25/hr (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Lake Crescent Lodge dinner","description":"Dinner at the historic 1915 lodge overlooking the lake \u2014 a perfect farewell. Watch for the sunset turning the water gold.","cost":"$55\u2013$85 for dinner (est.)","time":"5:30 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Hurricane Ridge","description":"The park's mountain crown: a 5,242-foot ridge with panoramic views from the Olympics to Canada. Paved nature trails, summer wildflowers, and deer and marmots that pose for photos.","officialUrl":"https://www.nps.gov/olym","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hurricane+Ridge+Port+Angeles+WA","price":"$30/vehicle entry (est.)","photos":["assets/pacific/images/olympic-wa-nature/attr1-1.jpg","assets/pacific/images/olympic-wa-nature/attr1-2.jpg","assets/pacific/images/olympic-wa-nature/attr1-3.jpg","assets/pacific/images/olympic-wa-nature/attr1-4.jpg"]},{"name":"Hoh Rain Forest","description":"One of the world's great temperate rainforests, draped in moss and receiving up to 14 feet of rain a year. The flat Hall of Mosses and Spruce Nature trails wind through 500-year-old trees.","officialUrl":"https://www.nps.gov/olym","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hoh+Rain+Forest+Forks+WA","price":"Included with entry (est.)","photos":["assets/pacific/images/olympic-wa-nature/attr2-1.jpg","assets/pacific/images/olympic-wa-nature/attr2-2.jpg","assets/pacific/images/olympic-wa-nature/attr2-3.jpg","assets/pacific/images/olympic-wa-nature/attr2-4.jpg"]},{"name":"Rialto Beach","description":"Wild Pacific beach of sea stacks, driftwood, and tide pools. The low-tide walk to Hole-in-the-Wall \u2014 a natural arch \u2014 is the classic Olympic beach hike.","officialUrl":"https://www.nps.gov/olym","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rialto+Beach+Forks+WA","price":"Included with entry (est.)","photos":["assets/pacific/images/olympic-wa-nature/attr3-1.jpg","assets/pacific/images/olympic-wa-nature/attr3-2.jpg","assets/pacific/images/olympic-wa-nature/attr3-3.jpg","assets/pacific/images/olympic-wa-nature/attr3-4.jpg"]},{"name":"Lake Crescent","description":"A deep, glacially carved lake of startling blue clarity. Swim at East Beach, kayak from the historic lodge, or walk the waterfall trail to Marymere Falls.","officialUrl":"https://www.nps.gov/olym","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake+Crescent+Port+Angeles+WA","price":"Included with entry (est.)","photos":["assets/pacific/images/olympic-wa-nature/attr4-1.jpg","assets/pacific/images/olympic-wa-nature/attr4-2.jpg","assets/pacific/images/olympic-wa-nature/attr4-3.jpg","assets/pacific/images/olympic-wa-nature/attr4-4.jpg"]}],"restaurants":[{"name":"Next Door Gastropub","detail":"Port Angeles favorite with creative burgers and a solid kids' menu.","price":"$$"},{"name":"Lake Crescent Lodge Dining Room","detail":"Historic lakeside dining \u2014 trout, steaks, and sunset views.","price":"$$"},{"name":"Sabai Thai","detail":"Cozy Port Angeles Thai spot; pad thai the kids will actually eat.","price":"$"}],"rainyDay":["Hurricane Ridge Visitor Center (films & exhibits)","Olympic National Park Visitor Center","Feiro Marine Life Center (Port Angeles)"],"driveNotes":"Olympic is big \u2014 the Hoh is 90 minutes from Port Angeles each way, so start early. Fill the tank before heading west; gas is scarce past Forks. Summer is the only reliable season for Hurricane Ridge road; check nps.gov for closures.","related":["mount-rainier-wa-nature","seattle-wa-city","san-juan-wa-islands"],"imageAsset":"assets/pacific/images/olympic-wa-nature/hero.jpg"},{"id":"mount-rainier-wa-nature","title":"Mount Rainier, WA: Three-Day Nature Escape","destination":"Mount Rainier, WA","state":"WA","stateName":"Washington","region":"Cascade Mountains","days":3,"tripType":"nature escape","interests":["family","outdoors","nature","scenic"],"budget":1300,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights lodge or nearby motel, meals, park entry, and gas.","tagline":"A 14,410-foot volcano wrapped in wildflower meadows and glaciers.","overview":"Mount Rainier dominates the skyline from 60 miles away \u2014 up close, it's staggering. Paradise's wildflower meadows bloom in August, Sunrise offers the mountain's closest roadside views, and waterfalls thunder all summer. Three days lets you savor both sides of the mountain without rushing. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk Paradise's wildflower meadows under the glaciers","See the mountain fill the sky at Sunrise Point","Feel the spray of 188-foot Narada Falls","Stand among 1,000-year-old cedars in the Grove of the Patriarchs","Spot marmots and mountain goats on the trails"],"bestSeason":"July\u2013September","familyFriendly":"Best for ages 6+. Paradise's lower trails (Nisqually Vista, Skyline lower section) are doable for kids; bring layers \u2014 it's 40\u00b0F cooler than Seattle.","lat":46.74098,"lng":-121.91675,"itinerary":[{"day":1,"title":"Paradise","morning":{"stop":"Paradise meadows","description":"Drive to Paradise (5,400 feet) and walk the Nisqually Vista Trail \u2014 wildflowers, marmots, and the mountain looming overhead. The visitor center's exhibits explain the glaciers.","cost":"$30/vehicle park entry (est.)","time":"10:00 AM \u2013 1:30 PM"},"afternoon":{"stop":"Skyline Trail lower section","description":"Hike part of the Skyline Trail toward Myrtle Falls \u2014 a 60-foot cascade with Rainier behind it, one of the park's classic photos. Turn back when little legs tire.","cost":"Free (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Paradise Inn dinner","description":"Dinner at the 1916 Paradise Inn's dining room \u2014 log-cabin grandeur with mountain views. Evening ranger talk if one's scheduled.","cost":"$55\u2013$85 for dinner (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Waterfalls & Old Growth","morning":{"stop":"Narada Falls","description":"Stop at the 188-foot Narada Falls \u2014 a short walk from the road to a viewpoint in the spray. Then continue to Reflection Lakes for the mirror-perfect mountain photo.","cost":"Included with entry (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Grove of the Patriarchs","description":"Walk the 1.1-mile boardwalk loop across the Ohanapecosh River to thousand-year-old cedars and firs \u2014 some 25 feet around. Magical and easy.","cost":"Included with entry (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Longmire evening","description":"Explore historic Longmire \u2014 the museum, the 1916 inn, and the Trail of the Shadows. Dinner at the National Park Inn.","cost":"$50\u2013$75 for dinner (est.)","time":"4:30 PM \u2013 7:30 PM"}},{"day":3,"title":"Sunrise Side","morning":{"stop":"Sunrise Point","description":"Drive around to Sunrise (6,400 feet) \u2014 the highest point reachable by car and the closest roadside views of the mountain. The Sourdough Ridge trail is an easy family walk with endless views.","cost":"Included with entry (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Sunrise picnic & visitor center","description":"Picnic with the mountain as your backdrop, then the Sunrise Visitor Center's exhibits. Watch for mountain goats on the ridgelines.","cost":"$30\u2013$45 picnic supplies (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Crystal Mountain gondola","description":"End with the gondola ride at Crystal Mountain Resort (just outside the park) \u2014 Rainier fills the entire window. Farewell dinner in Enumclaw.","cost":"Gondola $36/adult, $15/child (est.)","time":"4:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Paradise","description":"The park's most famous destination: subalpine meadows bursting with wildflowers beneath Rainier's glaciers. The Henry M. Jackson Visitor Center, Nisqually Vista Trail, and Myrtle Falls are all here.","officialUrl":"https://www.nps.gov/mora","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Paradise+Ashford+WA","price":"$30/vehicle entry (est.)","photos":["assets/pacific/images/mount-rainier-wa-nature/attr1-1.jpg","assets/pacific/images/mount-rainier-wa-nature/attr1-2.jpg","assets/pacific/images/mount-rainier-wa-nature/attr1-3.jpg","assets/pacific/images/mount-rainier-wa-nature/attr1-4.jpg"]},{"name":"Sunrise","description":"At 6,400 feet, the highest drivable point in the park \u2014 and the closest you can get to the summit by car. Sourdough Ridge offers easy walks with the 14,410-foot mountain dominating every view.","officialUrl":"https://www.nps.gov/mora","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sunrise+Greenwater+WA","price":"Included with entry (est.)","photos":["assets/pacific/images/mount-rainier-wa-nature/attr2-1.jpg","assets/pacific/images/mount-rainier-wa-nature/attr2-2.jpg","assets/pacific/images/mount-rainier-wa-nature/attr2-3.jpg","assets/pacific/images/mount-rainier-wa-nature/attr2-4.jpg"]},{"name":"Narada Falls","description":"A thundering 188-foot cascade just off the Paradise road. The short walk to the lower viewpoint puts you in the mist \u2014 and in winter it freezes into a glittering ice cone.","officialUrl":"https://www.nps.gov/mora","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Narada+Falls+Ashford+WA","price":"Included with entry (est.)","photos":["assets/pacific/images/mount-rainier-wa-nature/attr3-1.jpg","assets/pacific/images/mount-rainier-wa-nature/attr3-2.jpg","assets/pacific/images/mount-rainier-wa-nature/attr3-3.jpg","assets/pacific/images/mount-rainier-wa-nature/attr3-4.jpg"]},{"name":"Grove of the Patriarchs","description":"A boardwalk loop through ancient old-growth: thousand-year-old Douglas firs and cedars on an island in the Ohanapecosh River. Easy, flat, and humbling.","officialUrl":"https://www.nps.gov/mora","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Grove+of+the+Patriarchs+Packwood+WA","price":"Included with entry (est.)","photos":["assets/pacific/images/mount-rainier-wa-nature/attr4-1.jpg","assets/pacific/images/mount-rainier-wa-nature/attr4-2.jpg","assets/pacific/images/mount-rainier-wa-nature/attr4-3.jpg","assets/pacific/images/mount-rainier-wa-nature/attr4-4.jpg"]}],"restaurants":[{"name":"Paradise Inn Dining Room","detail":"Historic 1916 log lodge dining with mountain views \u2014 reservations smart.","price":"$$$"},{"name":"Copper Creek Inn","detail":"Ashford roadhouse with famous blackberry pie and hearty family fare.","price":"$$"},{"name":"Wildberry Restaurant","detail":"Sherpa family-owned spot a mile from the park entrance \u2014 momos, burgers, and famous marionberry pie.","price":"$"}],"rainyDay":["Longmire Museum & historic inn","Paradise visitor center films","Northwest Trek Wildlife Park (day trip)"],"driveNotes":"Summer weekends now require timed-entry reservations for the Paradise and Sunrise corridors \u2014 book on recreation.gov. Snow can close roads into July; check nps.gov before you go. Gas up in Ashford or Enumclaw \u2014 nothing inside the park.","related":["olympic-wa-nature","crater-lake-or-nature","yosemite-ca-nature"],"imageAsset":"assets/pacific/images/mount-rainier-wa-nature/hero.jpg"},{"id":"spokane-wa-city","title":"Spokane, WA: Three-Day Family Getaway","destination":"Spokane, WA","state":"WA","stateName":"Washington","region":"Eastern Washington","days":3,"tripType":"family getaway","interests":["family","outdoors","nature","museums","food"],"budget":1200,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, and attraction tickets.","tagline":"A waterfall downtown, a park built for a World's Fair, and the friendliest city east of the Cascades.","overview":"Spokane surprises first-timers: a thundering waterfall runs right through downtown, wrapped in a 100-acre park from the 1974 World's Fair. Add lilac gardens, a hands-on discovery center, and easy river trails, and you've got a relaxed, affordable family weekend. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride the gondola over Spokane Falls","Smell the lilacs at Manito Park's gardens","Build and splash at Mobius Discovery Center","Walk the riverside trails of Riverside State Park","Ride the 1909 Looff carousel in Riverfront Park"],"bestSeason":"May\u2013October","familyFriendly":"Best for all ages. Riverfront Park is flat and stroller-friendly; the falls are most dramatic in spring runoff.","lat":47.65726,"lng":-117.41162,"itinerary":[{"day":1,"title":"Riverfront Park","morning":{"stop":"Spokane Falls & gondola","description":"Start at Riverfront Park and ride the Numerica SkyRide gondola directly over the roaring Spokane Falls \u2014 the spring flow is thunderous. Walk the upper falls viewpoint for photos.","cost":"Gondola $10/adult, $7/child (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Park attractions & lunch","description":"Ride the 1909 Looff carousel (hand-carved horses), visit the SkyRibbon sculpture, and lunch at a downtown caf\u00e9. The park's playgrounds and splash pad entertain for hours.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:30 PM"},"evening":{"stop":"Downtown dinner","description":"Dinner downtown \u2014 the historic Davenport area has great family options. Evening stroll along the river as the falls light up.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Gardens & Discovery","morning":{"stop":"Manito Park","description":"Wander the 90-acre park's Duncan formal gardens, rose garden, and Japanese garden \u2014 free and gorgeous. The conservatory's tropical plants are a hit with kids.","cost":"Free; conservatory donation (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Mobius Discovery Center","description":"An afternoon of hands-on building, water play, and climbing at the children's discovery center. The outdoor play space is great in summer.","cost":"$12/person (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"South Hill dinner","description":"Dinner on the South Hill \u2014 pizza or burgers, then ice cream. Low-key and local.","cost":"$45\u2013$65 for dinner (est.)","time":"5:00 PM \u2013 7:30 PM"}},{"day":3,"title":"River Trails","morning":{"stop":"Riverside State Park","description":"Hike or bike the riverside trails at Bowl and Pitcher \u2014 basalt cliffs, swinging bridge, and swimming holes. The 1-mile loop is easy for kids.","cost":"$10 day use (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Northwest Museum lunch","description":"Lunch nearby, then the Northwest Museum of Arts and Culture \u2014 the Plateau Indian exhibits and historic Campbell House interest older kids.","cost":"Museum $12/adult, $7/child (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Farewell falls","description":"One last look at the falls from Huntington Park at sunset, then dinner downtown before departure.","cost":"$45\u2013$65 for dinner (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Riverfront Park","description":"The 100-acre downtown park from Expo '74, built around the spectacular Spokane Falls. Ride the gondola over the falls, the 1909 Looff carousel, and miles of riverside paths.","officialUrl":"https://riverfrontspokane.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Riverfront+Park+Spokane+WA","price":"Park free; rides $7\u2013$10 (est.)","photos":["assets/pacific/images/spokane-wa-city/attr1-1.jpg","assets/pacific/images/spokane-wa-city/attr1-2.jpg","assets/pacific/images/spokane-wa-city/attr1-3.jpg","assets/pacific/images/spokane-wa-city/attr1-4.jpg"]},{"name":"Manito Park","description":"Ninety acres of free gardens: formal Duncan Gardens, a rose garden with 1,500 bushes, a Japanese garden, and a tropical conservatory. Spokane's backyard since 1904.","officialUrl":"https://www.manitopark.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Manito+Park+Spokane+WA","price":"Free (est.)","photos":["assets/pacific/images/spokane-wa-city/attr2-1.jpg","assets/pacific/images/spokane-wa-city/attr2-2.jpg","assets/pacific/images/spokane-wa-city/attr2-3.jpg","assets/pacific/images/spokane-wa-city/attr2-4.jpg"]},{"name":"Mobius Discovery Center","description":"Hands-on children's museum with building zones, a water table the size of a room, and an outdoor play space. Designed for ages 8 and under but fun for the whole family.","officialUrl":"https://mobiusdiscoverycenter.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mobius+Discovery+Center+Spokane+WA","price":"$12/person (est.)","photos":["assets/pacific/images/spokane-wa-city/attr3-1.jpg","assets/pacific/images/spokane-wa-city/attr3-2.jpg","assets/pacific/images/spokane-wa-city/attr3-3.jpg","assets/pacific/images/spokane-wa-city/attr3-4.jpg"]},{"name":"Riverside State Park","description":"Washington's largest state park hugs the Spokane River with basalt cliffs, the Bowl and Pitcher swinging bridge, and swimming holes. Miles of easy riverside trails.","officialUrl":"https://www.parks.wa.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Riverside+State+Park+Spokane+WA","price":"$10 day use (est.)","photos":["assets/pacific/images/spokane-wa-city/attr4-1.jpg","assets/pacific/images/spokane-wa-city/attr4-2.jpg","assets/pacific/images/spokane-wa-city/attr4-3.jpg","assets/pacific/images/spokane-wa-city/attr4-4.jpg"]}],"restaurants":[{"name":"Clinkerdagger","detail":"Upscale-casual on the river with falls views \u2014 great steaks and a kids' menu.","price":"$$$"},{"name":"Dick's Hamburgers","detail":"Spokane institution since 1965 \u2014 classic burgers, fries, and shakes.","price":"$"},{"name":"Twigs Bistro","detail":"Lively bistro with martinis for parents and mac-and-cheese for kids.","price":"$$"}],"rainyDay":["Mobius Discovery Center (indoors)","Northwest Museum of Arts and Culture","Spokane Public Library Central (kids' floor)"],"driveNotes":"Spokane is an easy driving city \u2014 downtown parking is cheap and everything is 15 minutes apart. It's 4 hours from Seattle over Snoqualmie Pass; check pass conditions in winter. Summer wildfire smoke can occasionally haze the skies.","related":["seattle-wa-city","san-juan-wa-islands","bend-or-outdoors"],"imageAsset":"assets/pacific/images/spokane-wa-city/hero.jpg"},{"id":"san-juan-wa-islands","title":"San Juan Islands, WA: Three-Day Island Escape","destination":"San Juan Islands, WA","state":"WA","stateName":"Washington","region":"San Juan Islands","days":3,"tripType":"island escape","interests":["family","outdoors","nature","scenic","beaches"],"budget":2000,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights island inn, meals, ferry fares, and attraction tickets.","tagline":"Orca waters, a lighthouse on the whale highway, and island time at its slowest.","overview":"The San Juans are the Pacific Northwest's island dream \u2014 orcas cruising past a lighthouse point, lavender farms, and a harbor town with ice cream on every corner. Base on San Juan Island (Friday Harbor) and you can see it all without moving the car. The ferry ride over is half the adventure. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Watch for orcas from Lime Kiln Point's lighthouse","Meet the orca skeleton at The Whale Museum","Walk the prairies of American Camp","Kayak with harbor seals in the bays","Ride the Washington State Ferry through the islands"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 5+. Ferries and island roads are easy; whale sightings aren't guaranteed, so frame it as a bonus.","lat":48.46356,"lng":-122.96376,"itinerary":[{"day":1,"title":"Ferry & Friday Harbor","morning":{"stop":"Ferry to Friday Harbor","description":"Sail from Anacortes (book vehicle reservations ahead) \u2014 the 60\u201390 minute ride threads between forested islands. Watch for seals and eagles from the deck.","cost":"Ferry ~$60/vehicle + passengers (est.)","time":"9:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Friday Harbor","description":"Lunch on the waterfront, then explore the shops and the historic waterfront. The Whale Museum's orca skeletons and hydrophone listening station fascinate kids.","cost":"Museum $10/adult, $5/child (est.)","time":"12:30 PM \u2013 4:30 PM"},"evening":{"stop":"Harbor sunset","description":"Dinner overlooking the marina \u2014 watch sailboats and the ferry come and go. Evening walk on the docks to spot jellyfish.","cost":"$55\u2013$80 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Whales & History","morning":{"stop":"Lime Kiln Point State Park","description":"Drive to the west side's lighthouse \u2014 nicknamed Whale Watch Park, it's one of the best land-based orca viewpoints in the world. Summer afternoons bring the best odds.","cost":"$10 day use (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Whale watch tour","description":"Take an afternoon whale-watch boat from Friday Harbor \u2014 naturalists narrate, and you'll likely see orcas, humpbacks, seals, and bald eagles. Three hours on the water.","cost":"$110/adult, $80/child (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Roche Harbor evening","description":"Drive to storybook Roche Harbor \u2014 historic hotel, marina, and the nightly Colors Ceremony (flag lowering) in summer. Dinner at the village restaurant.","cost":"$55\u2013$85 for dinner (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Prairies & Farewell","morning":{"stop":"San Juan Island National Historical Park","description":"Explore American Camp's windswept prairies and South Beach \u2014 driftwood, eagles, and the story of the Pig War. The visitor center has a great kids' scavenger hunt.","cost":"Free (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Lavender farm & alpacas","description":"Stop at Pelindaba Lavender Farm (summer) or Krystal Acres alpaca farm for a gentle afternoon. Ice cream in Friday Harbor before the ferry.","cost":"$20\u2013$35 for farm visits (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Ferry home","description":"Catch the late-afternoon ferry back to Anacortes. The sunset sail through the islands is the perfect farewell.","cost":"Included in round trip (est.)","time":"4:00 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Lime Kiln Point State Park","description":"A lighthouse on the west side's 'whale highway' \u2014 one of the world's best spots to see orcas from shore. Summer afternoons bring pods past the point; the lighthouse and interpretive center add context.","officialUrl":"https://www.parks.wa.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lime+Kiln+Point+State+Park+Friday+Harbor+WA","price":"$10 day use (est.)","photos":["assets/pacific/images/san-juan-wa-islands/attr1-1.jpg","assets/pacific/images/san-juan-wa-islands/attr1-2.jpg","assets/pacific/images/san-juan-wa-islands/attr1-3.jpg","assets/pacific/images/san-juan-wa-islands/attr1-4.jpg"]},{"name":"San Juan Island National Historical Park","description":"Two historic camps \u2014 American and English \u2014 from the 1859 'Pig War' standoff. American Camp's prairies, beaches, and eagle nests make it a wonderful family walk.","officialUrl":"https://www.nps.gov/sajh","mapsUrl":"https://www.google.com/maps/search/?api=1&query=San+Juan+Island+National+Historical+Park+Friday+Harbor+WA","price":"Free (est.)","photos":["assets/pacific/images/san-juan-wa-islands/attr2-1.jpg","assets/pacific/images/san-juan-wa-islands/attr2-2.jpg","assets/pacific/images/san-juan-wa-islands/attr2-3.jpg","assets/pacific/images/san-juan-wa-islands/attr2-4.jpg"]},{"name":"The Whale Museum","description":"America's first museum devoted to whales: full orca skeletons, a hydrophone listening station with live underwater sound, and exhibits on the resident orca pods.","officialUrl":"https://www.whalemuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The+Whale+Museum+Friday+Harbor+WA","price":"$10/adult, $5/child (est.)","photos":["assets/pacific/images/san-juan-wa-islands/attr3-1.jpg","assets/pacific/images/san-juan-wa-islands/attr3-2.jpg","assets/pacific/images/san-juan-wa-islands/attr3-3.jpg","assets/pacific/images/san-juan-wa-islands/attr3-4.jpg"]},{"name":"Roche Harbor","description":"A historic company town turned storybook marina village \u2014 the 1886 Hotel de Haro, manicured gardens, and the summer Colors Ceremony. Feels like stepping back a century.","officialUrl":"https://www.rocheharbor.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Roche+Harbor+Roche+Harbor+WA","price":"Free (est.)","photos":["assets/pacific/images/san-juan-wa-islands/attr4-1.jpg","assets/pacific/images/san-juan-wa-islands/attr4-2.jpg","assets/pacific/images/san-juan-wa-islands/attr4-3.jpg","assets/pacific/images/san-juan-wa-islands/attr4-4.jpg"]}],"restaurants":[{"name":"Downriggers","detail":"Waterfront spot on the marina \u2014 fish and chips with harbor views.","price":"$$"},{"name":"Duck Soup Inn","detail":"Cozy inn restaurant in the woods; refined but welcoming to families.","price":"$$$"},{"name":"Cask & Schooner","detail":"British-style pub on the waterfront with great fish tacos.","price":"$$"}],"rainyDay":["The Whale Museum (indoors)","San Juan Historical Museum","Island Cinema (Friday Harbor movie theater)"],"driveNotes":"Book Washington State Ferry vehicle reservations as early as possible \u2014 summer sailings sell out. You can also walk on and rent bikes or mopeds on the island. Everything on San Juan Island is within 20 minutes; Orcas and Lopez are separate ferry hops.","related":["seattle-wa-city","olympic-wa-nature","cannon-beach-or-coast"],"imageAsset":"assets/pacific/images/san-juan-wa-islands/hero.jpg"},{"id":"oahu-hi-beach","title":"Oahu, HI: Four-Day Island Adventure","destination":"Oahu, HI","state":"HI","stateName":"Hawaii","region":"Oahu","days":4,"tripType":"island adventure","interests":["family","beaches","nature","historical-sites","food"],"budget":3400,"budgetNote":"Est. for 2 adults + 2 kids: 3 nights mid-range Waikiki hotel, meals, rental car, and attraction tickets.","tagline":"Surf, history, and shave ice \u2014 the island that has a little of everything Hawaii.","overview":"Oahu is Hawaii's greatest-hits island: Waikiki's gentle surf, Pearl Harbor's moving history, Diamond Head's crater views, and the North Shore's big waves. Four days lets you mix beach time with culture without the rush \u2014 and the food scene alone is worth the flight. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Learn to surf on Waikiki's gentle waves","Honor history at Pearl Harbor's USS Arizona Memorial","Hike Diamond Head crater for sunrise","Watch big-wave surfers at Banzai Pipeline","Feast and dance at a traditional luau"],"bestSeason":"Year-round","familyFriendly":"Best for all ages. Waikiki's protected beach is ideal for first-time swimmers; Pearl Harbor moves older kids deeply.","lat":21.27946,"lng":-157.82617,"itinerary":[{"day":1,"title":"Waikiki Beach Day","morning":{"stop":"Waikiki Beach","description":"Claim a spot on the world's most famous beach. The waves are gentle and the water warm \u2014 perfect for first-time boogie boarders. Take a group surf lesson; most kids stand up in an hour.","cost":"Surf lesson ~$80/person (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Lunch & Duke's statue","description":"Lunch on Kalakaua Avenue \u2014 poke bowls and shave ice. Visit the Duke Kahanamoku statue and let the kids play at the Kuhio Beach playground.","cost":"$50\u2013$75 for lunch (est.)","time":"1:00 PM \u2013 4:30 PM"},"evening":{"stop":"Sunset catamaran","description":"Sail into the sunset on a Waikiki catamaran \u2014 Diamond Head glowing, sea turtles surfacing. Dinner back on the strip.","cost":"Catamaran $45/adult, $25/child (est.)","time":"5:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Pearl Harbor & History","morning":{"stop":"Pearl Harbor National Memorial","description":"Book USS Arizona Memorial tickets ahead (recreation.gov) \u2014 the boat ride and memorial are profoundly moving. The visitor center's museums take two hours; older kids are riveted.","cost":"Free; parking $7 (est.)","time":"8:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"USS Missouri & lunch","description":"Walk Ford Island to the Battleship Missouri \u2014 stand on the deck where WWII ended. Lunch at the memorial caf\u00e9 or back in Honolulu.","cost":"Missouri $35/adult, $18/child (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Honolulu evening","description":"Dinner in Honolulu \u2014 the city's food scene shines. Stroll the lit-up Waikiki Beach Walk after.","cost":"$60\u2013$90 for dinner (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Diamond Head & East Side","morning":{"stop":"Diamond Head sunrise hike","description":"Enter at 6 AM opening and hike the 1.6-mile trail to the 761-foot summit for sunrise over Waikiki. The tunnel and spiral staircase are an adventure in themselves.","cost":"$5/person entry (est.)","time":"6:00 AM \u2013 9:30 AM"},"afternoon":{"stop":"Hanauma Bay","description":"Snorkel the curved bay's coral gardens \u2014 sea turtles guaranteed. Book entry ahead; the bay closes some days for rest. Mandatory 9-minute orientation film.","cost":"$25/adult, kids free (est.)","time":"10:30 AM \u2013 2:30 PM"},"evening":{"stop":"Luau evening","description":"A traditional luau \u2014 imu ceremony, hula, fire dancing, and a feast. Paradise Cove or Germaine's are family favorites. Book ahead.","cost":"$130\u2013$160/adult, $90\u2013$110/child (est.)","time":"5:00 PM \u2013 9:00 PM"}},{"day":4,"title":"North Shore","morning":{"stop":"Drive the North Shore","description":"Circle the island: stop at the Dole Plantation's pineapple maze (kids love it), then Haleiwa town for shave ice at Matsumoto's.","cost":"Maze $12/person (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Waimea Bay & Pipeline","description":"In summer, swim Waimea Bay's calm waters; in winter, watch 30-foot waves at Banzai Pipeline from the beach. The shrimp trucks at Kahuku are lunch.","cost":"$40\u2013$60 for lunch (est.)","time":"1:00 PM \u2013 4:30 PM"},"evening":{"stop":"Polynesian Cultural Center","description":"End at the PCC \u2014 six island villages, canoe rides, and the evening H\u0101: Breath of Life show. A full cultural immersion.","cost":"$80\u2013$130/adult, $60\u2013$100/child (est.)","time":"5:00 PM \u2013 9:00 PM"}}],"attractions":[{"name":"Waikiki Beach","description":"The world's most famous beach: two miles of gentle surf, warm water, and Diamond Head on the horizon. Take a surf lesson, sail a catamaran at sunset, or just float.","officialUrl":"https://www.gohawaii.com/islands/oahu/regions/honolulu/waikiki","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Waikiki+Beach+Honolulu+HI","price":"Free; lessons ~$80 (est.)","photos":["assets/pacific/images/oahu-hi-beach/attr1-1.jpg","assets/pacific/images/oahu-hi-beach/attr1-2.jpg","assets/pacific/images/oahu-hi-beach/attr1-3.jpg","assets/pacific/images/oahu-hi-beach/attr1-4.jpg"]},{"name":"Pearl Harbor National Memorial","description":"The USS Arizona Memorial \u2014 a white bridge over the sunken battleship \u2014 plus world-class museums on the attack. Free timed tickets via recreation.gov; book weeks ahead.","officialUrl":"https://www.nps.gov/valr","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pearl+Harbor+National+Memorial+Honolulu+HI","price":"Free; parking $7 (est.)","photos":["assets/pacific/images/oahu-hi-beach/attr2-1.jpg","assets/pacific/images/oahu-hi-beach/attr2-2.jpg","assets/pacific/images/oahu-hi-beach/attr2-3.jpg","assets/pacific/images/oahu-hi-beach/attr2-4.jpg"]},{"name":"Diamond Head State Monument","description":"Hike the 1.6-mile trail up the 300,000-year-old volcanic crater to 761 feet for the definitive Waikiki panorama. Sunrise slots are magical \u2014 and bookable.","officialUrl":"https://dlnr.hawaii.gov/dsp/parks/oahu/diamond-head-state-monument","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Diamond+Head+State+Monument+Honolulu+HI","price":"$5/person (est.)","photos":["assets/pacific/images/oahu-hi-beach/attr3-1.jpg","assets/pacific/images/oahu-hi-beach/attr3-2.jpg","assets/pacific/images/oahu-hi-beach/attr3-3.jpg","assets/pacific/images/oahu-hi-beach/attr3-4.jpg"]},{"name":"Polynesian Cultural Center","description":"Six Pacific island villages with hands-on crafts, canoe rides, and the spectacular evening show H\u0101: Breath of Life. A full day of living culture.","officialUrl":"https://www.polynesia.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Polynesian+Cultural+Center+Laie+HI","price":"$80\u2013$130/adult (est.)","photos":["assets/pacific/images/oahu-hi-beach/attr4-1.jpg","assets/pacific/images/oahu-hi-beach/attr4-2.jpg","assets/pacific/images/oahu-hi-beach/attr4-3.jpg","assets/pacific/images/oahu-hi-beach/attr4-4.jpg"]}],"restaurants":[{"name":"Duke's Waikiki","detail":"Beachfront legend \u2014 hula pie, live music, and sunset views from the sand.","price":"$$"},{"name":"Helena's Hawaiian Food","detail":"James Beard-winning local spot \u2014 pipikaula short ribs and poi, cash-friendly.","price":"$"},{"name":"Leonard's Bakery","detail":"Malasadas (Portuguese doughnuts) hot from the fryer since 1952 \u2014 a pilgrimage.","price":"$"}],"rainyDay":["Bishop Museum (Hawaiian culture & science)","Pearl Harbor museums (indoors)","Waikiki Aquarium"],"driveNotes":"Oahu's H-1 freeway clogs at rush hour \u2014 plan around it. Waikiki hotel parking runs $35\u2013$50/night (est.); many families skip the car for Waikiki days and rent only for the North Shore. Book Pearl Harbor, Hanauma Bay, and Diamond Head ahead.","related":["maui-hi-beach","kauai-hi-nature","big-island-hi-adventure"],"imageAsset":"assets/pacific/images/oahu-hi-beach/hero.jpg"},{"id":"maui-hi-beach","title":"Maui, HI: Four-Day Island Adventure","destination":"Maui, HI","state":"HI","stateName":"Hawaii","region":"Maui","days":4,"tripType":"island adventure","interests":["family","beaches","nature","scenic","outdoors"],"budget":3800,"budgetNote":"Est. for 2 adults + 2 kids: 3 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"Sunrise above the clouds, waterfalls along the Hana highway, and beaches that ruin all other beaches.","overview":"Maui is the honeymoon island that happens to be perfect for families too. Watch sunrise from 10,000-foot Haleakal\u0101, wind the Road to Hana past waterfall after waterfall, and snorkel with turtles at Ka'anapali. Four days balances adventure days with pure beach days. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Watch sunrise above the clouds at Haleakal\u0101","Swim in waterfall pools along the Road to Hana","Snorkel with sea turtles at Ka'anapali Beach","See sharks and rays at the Maui Ocean Center","Drive the Road to Hana's 600+ curves"],"bestSeason":"Year-round","familyFriendly":"Best for all ages. Haleakal\u0101 is cold at sunrise (bring jackets!); the Road to Hana suits kids who handle car time.","lat":20.89096,"lng":-156.46724,"itinerary":[{"day":1,"title":"Haleakal\u0101 Sunrise","morning":{"stop":"Haleakal\u0101 sunrise","description":"Book a sunrise reservation and drive to the 10,023-foot summit in the dark. Watch the sun ignite a sea of clouds from above \u2014 then walk the otherworldly Sliding Sands trail rim. It's 40\u00b0F: bring every jacket.","cost":"$1/vehicle reservation (est.)","time":"3:30 AM \u2013 9:00 AM"},"afternoon":{"stop":"Upcountry & lunch","description":"Descend through Upcountry Maui \u2014 stop at the lavender farm or goat dairy, then lunch in Makawao's paniolo (cowboy) town.","cost":"$50\u2013$75 for lunch (est.)","time":"10:00 AM \u2013 2:00 PM"},"evening":{"stop":"Beach recovery","description":"Nap, then a mellow afternoon at your hotel beach. Early dinner \u2014 you earned it after the 3 AM wake-up.","cost":"$60\u2013$90 for dinner (est.)","time":"3:00 PM \u2013 7:30 PM"}},{"day":2,"title":"Road to Hana","morning":{"stop":"Road to Hana: west side","description":"Leave by 7 AM for the famous highway \u2014 64 miles, 600 curves, 59 bridges. Stop at Twin Falls (swim!), the Garden of Eden, and the Ke'anae Peninsula's lava coast.","cost":"Free; stops $5\u2013$15 (est.)","time":"7:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Hana & Wai'anapanapa","description":"Black sand beach at Wai'anapanapa State Park \u2014 swim in the sea cave pool. Lunch in Hana town, then the Pipiwai Trail's bamboo forest (2 miles to the 400-foot Waimoku Falls) if energy allows.","cost":"$5/person park entry (est.)","time":"1:00 PM \u2013 5:30 PM"},"evening":{"stop":"Return drive","description":"Drive back the same stunning road (or the adventurous back side if your rental allows). Quiet dinner near the hotel \u2014 it's a long day.","cost":"$50\u2013$75 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":3,"title":"Ocean Day","morning":{"stop":"Maui Ocean Center","description":"The 'Hawaiian Aquarium': walk the 54-foot shark tunnel, meet Hawaiian monk seals, and touch tide-pool creatures. The 3D humpback whale film is spectacular.","cost":"$55/adult, $40/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Ka'anapali Beach","description":"Afternoon at Ka'anapali \u2014 three miles of golden sand. Snorkel Black Rock's turtle-filled waters, then watch the nightly cliff-diving ceremony at sunset.","cost":"Free (est.)","time":"1:30 PM \u2013 5:30 PM"},"evening":{"stop":"Whalers Village dinner","description":"Dinner at the open-air Whalers Village \u2014 the free hula show and the whaling museum entertain between courses.","cost":"$60\u2013$90 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":4,"title":"South Maui Farewell","morning":{"stop":"Molokini snorkel trip","description":"Morning boat to Molokini Crater \u2014 a crescent-shaped volcanic atoll with 150-foot visibility. Turtles, reef fish, and maybe dolphins on the ride.","cost":"$150/adult, $110/child (est.)","time":"7:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Wailea beaches","description":"Lunch in Kihei, then the calm, kid-perfect beaches of Wailea \u2014 Ulua Beach's gentle snorkeling is ideal for beginners.","cost":"$45\u2013$65 for lunch (est.)","time":"12:30 PM \u2013 4:30 PM"},"evening":{"stop":"Old Lahaina Luau","description":"End with Maui's most beloved luau \u2014 oceanfront, traditional, and unforgettable. Book well ahead.","cost":"$140\u2013$180/adult, $90\u2013$120/child (est.)","time":"5:00 PM \u2013 9:00 PM"}}],"attractions":[{"name":"Haleakal\u0101 National Park","description":"A 10,023-foot dormant volcano with sunrise above the clouds, the otherworldly Sliding Sands crater trail, and endangered silversword plants. Sunrise requires a reservation.","officialUrl":"https://www.nps.gov/hale","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Haleakal%C4%81+National+Park+Kula+HI","price":"$30/vehicle (est.)","photos":["assets/pacific/images/maui-hi-beach/attr1-1.jpg","assets/pacific/images/maui-hi-beach/attr1-2.jpg","assets/pacific/images/maui-hi-beach/attr1-3.jpg","assets/pacific/images/maui-hi-beach/attr1-4.jpg"]},{"name":"Road to Hana","description":"The legendary 64-mile highway: 600 curves past waterfalls, black-sand beaches, bamboo forests, and the 400-foot Waimoku Falls. Leave early, pack snacks, and stop often.","officialUrl":"https://www.gohawaii.com/islands/maui/regions/east-maui/Hana","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Road+to+Hana+Hana+HI","price":"Free (est.)","photos":["assets/pacific/images/maui-hi-beach/attr2-1.jpg","assets/pacific/images/maui-hi-beach/attr2-2.jpg","assets/pacific/images/maui-hi-beach/attr2-3.jpg","assets/pacific/images/maui-hi-beach/attr2-4.jpg"]},{"name":"Maui Ocean Center","description":"All-Hawaiian aquarium with a 54-foot shark tunnel, living reef exhibits, and the 3D Sphere humpback-whale film. The cultural exhibits connect marine life to Hawaiian tradition.","officialUrl":"https://www.mauioceancenter.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Maui+Ocean+Center+Wailuku+HI","price":"$55/adult, $40/child (est.)","photos":["assets/pacific/images/maui-hi-beach/attr3-1.jpg","assets/pacific/images/maui-hi-beach/attr3-2.jpg","assets/pacific/images/maui-hi-beach/attr3-3.jpg","assets/pacific/images/maui-hi-beach/attr3-4.jpg"]},{"name":"Ka'anapali Beach","description":"Three miles of golden sand voted among America's best beaches. Snorkel with turtles at Black Rock, watch the sunset cliff-diving ceremony, and stroll the beachwalk.","officialUrl":"https://www.gohawaii.com/islands/maui/regions/west-maui/kaanapali-beach","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Ka%27anapali+Beach+Lahaina+HI","price":"Free (est.)","photos":["assets/pacific/images/maui-hi-beach/attr4-1.jpg","assets/pacific/images/maui-hi-beach/attr4-2.jpg","assets/pacific/images/maui-hi-beach/attr4-3.jpg","assets/pacific/images/maui-hi-beach/attr4-4.jpg"]}],"restaurants":[{"name":"Mama's Fish House","detail":"The legendary oceanfront splurge \u2014 the day's catch listed with the fisherman's name.","price":"$$$"},{"name":"Leoda's Kitchen and Pie Shop","detail":"Roadside pie shop on the way to Lahaina \u2014 the olallieberry pie is famous.","price":"$"},{"name":"Ululani's Hawaiian Shave Ice","detail":"The island's best shave ice \u2014 get it with ice cream on the bottom.","price":"$"}],"rainyDay":["Maui Ocean Center (indoors)","Alexander & Baldwin Sugar Museum","Maui Mall movie & shops"],"driveNotes":"Maui demands a rental car. The Road to Hana is a full 10\u201312 hour day \u2014 start by 7 AM and check whether your rental contract allows the back road (most don't). Haleakal\u0101 sunrise needs a reservation booked ahead on recreation.gov.","related":["oahu-hi-beach","kauai-hi-nature","big-island-hi-adventure"],"imageAsset":"assets/pacific/images/maui-hi-beach/hero.jpg"},{"id":"kauai-hi-nature","title":"Kauai, HI: Three-Day Nature Escape","destination":"Kauai, HI","state":"HI","stateName":"Hawaii","region":"Kauai","days":3,"tripType":"nature escape","interests":["family","beaches","nature","scenic","outdoors"],"budget":2900,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"The Garden Island \u2014 canyons, cathedral cliffs, and waterfalls in every direction.","overview":"Kauai is Hawaii at its lushest and least hurried \u2014 the 'Grand Canyon of the Pacific,' the cathedral cliffs of the N\u0101 Pali Coast, and waterfalls you can swim beneath. Three days covers the canyon, a N\u0101 Pali boat day, and the sunny south shore's beaches. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Gaze into Waimea Canyon's red-rock depths","Sail beneath the N\u0101 Pali Coast's 4,000-foot cliffs","Swim at Po'ip\u016b Beach with monk seals nearby","Stand behind the curtain of Wailua Falls","Tube the old sugar plantation flumes"],"bestSeason":"Year-round","familyFriendly":"Best for ages 6+. Canyon viewpoints are easy; N\u0101 Pali boat tours suit kids who handle open water.","lat":21.97504,"lng":-159.3691,"itinerary":[{"day":1,"title":"Waimea Canyon","morning":{"stop":"Waimea Canyon lookouts","description":"Drive Waimea Canyon Drive to the main lookout \u2014 3,000 feet deep, 10 miles long, impossibly red and green. Continue to Kalalau Lookout for the N\u0101 Pali valley view.","cost":"Free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Canyon trails & lunch","description":"Walk the easy 0.25-mile Iliau Nature Loop, then picnic at Kokee. The Kokee Museum's exhibits explain the island's unique birds.","cost":"$30\u2013$45 picnic supplies (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"West side sunset","description":"Drive down to Kekaha Beach for sunset \u2014 the longest white-sand beach on Kauai. Dinner in Waimea town.","cost":"$50\u2013$75 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"N\u0101 Pali Coast","morning":{"stop":"N\u0101 Pali boat tour","description":"Sail from Port Allen up the N\u0101 Pali Coast \u2014 4,000-foot sea cliffs, waterfalls pouring into the ocean, dolphins riding the bow. Catamaran tours include snorkeling.","cost":"$180/adult, $140/child (est.)","time":"8:00 AM \u2013 2:00 PM"},"afternoon":{"stop":"Port Allen & lunch","description":"Lunch back at the harbor, then a quiet afternoon \u2014 the morning's boat ride is the day's main event. Rest at the hotel pool.","cost":"$45\u2013$65 for lunch (est.)","time":"2:30 PM \u2013 5:00 PM"},"evening":{"stop":"Po'ip\u016b dinner","description":"Drive to Po'ip\u016b for dinner \u2014 sunset over the south shore. The kids can hunt for crabs on the rocks at Brennecke's Beach.","cost":"$60\u2013$90 for dinner (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Waterfalls & South Shore","morning":{"stop":"Wailua Falls & Opaeka'a","description":"Drive the east side: Opaeka'a Falls viewpoint, then Wailua Falls \u2014 the 173-foot twin falls from Fantasy Island's opening credits. Quick, gorgeous stops.","cost":"Free (est.)","time":"9:00 AM \u2013 11:30 AM"},"afternoon":{"stop":"Po'ip\u016b Beach","description":"Swim and snorkel at Po'ip\u016b Beach Park \u2014 lifeguarded, with monk seals often napping on the sand (give them 50 feet). Lunch at the beach park.","cost":"$40\u2013$60 for lunch (est.)","time":"12:00 PM \u2013 4:00 PM"},"evening":{"stop":"Spouting Horn & farewell","description":"End at Spouting Horn \u2014 ocean blowhole blasting 50 feet in the air. Farewell shave ice in Koloa town.","cost":"$20 shave ice & souvenirs (est.)","time":"4:30 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Waimea Canyon State Park","description":"The 'Grand Canyon of the Pacific': 3,000 feet deep and 10 miles long, streaked red, green, and black. Drive-up lookouts make it effortless; the Iliau Nature Loop adds an easy walk.","officialUrl":"https://dlnr.hawaii.gov/dsp/parks/kauai/waimea-canyon-state-park","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Waimea+Canyon+State+Park+Waimea+HI","price":"Free (est.)","photos":["assets/pacific/images/kauai-hi-nature/attr1-1.jpg","assets/pacific/images/kauai-hi-nature/attr1-2.jpg","assets/pacific/images/kauai-hi-nature/attr1-3.jpg","assets/pacific/images/kauai-hi-nature/attr1-4.jpg"]},{"name":"N\u0101 Pali Coast","description":"Seventeen miles of 4,000-foot sea cliffs, hanging valleys, and waterfalls \u2014 unreachable by road. See it by boat tour (with snorkeling and dolphins) or helicopter.","officialUrl":"https://www.gohawaii.com/islands/kauai/regions/north-shore/napali-coast","mapsUrl":"https://www.google.com/maps/search/?api=1&query=N%C4%81+Pali+Coast+Kauai+HI","price":"Boat tours $140\u2013$200 (est.)","photos":["assets/pacific/images/kauai-hi-nature/attr2-1.jpg","assets/pacific/images/kauai-hi-nature/attr2-2.jpg","assets/pacific/images/kauai-hi-nature/attr2-3.jpg","assets/pacific/images/kauai-hi-nature/attr2-4.jpg"]},{"name":"Wailua Falls","description":"Twin 173-foot waterfalls plunging into a fern-draped pool \u2014 famous from Fantasy Island. An easy drive-up viewpoint on the east side; rainbows most mornings.","officialUrl":"https://www.gohawaii.com/islands/kauai/regions/lihue/wailua-falls","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wailua+Falls+Lihue+HI","price":"Free (est.)","photos":["assets/pacific/images/kauai-hi-nature/attr3-1.jpg","assets/pacific/images/kauai-hi-nature/attr3-2.jpg","assets/pacific/images/kauai-hi-nature/attr3-3.jpg","assets/pacific/images/kauai-hi-nature/attr3-4.jpg"]},{"name":"Po'ip\u016b Beach Park","description":"Kauai's best family beach: lifeguarded, gentle snorkeling, and frequent Hawaiian monk seal sightings. Brennecke's Beach next door has tide pools and bodyboarding.","officialUrl":"https://www.gohawaii.com/islands/kauai/regions/south-shore/poipu-beach-park","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Po%27ip%C5%AB+Beach+Park+Koloa+HI","price":"Free (est.)","photos":["assets/pacific/images/kauai-hi-nature/attr4-1.jpg","assets/pacific/images/kauai-hi-nature/attr4-2.jpg","assets/pacific/images/kauai-hi-nature/attr4-3.jpg","assets/pacific/images/kauai-hi-nature/attr4-4.jpg"]}],"restaurants":[{"name":"Puka Dog","detail":"Hawaiian-style hot dogs in sweet bread with tropical relishes \u2014 a Po'ip\u016b institution.","price":"$"},{"name":"Hamura Saimin","detail":"Lihue noodle shop since 1952 \u2014 saimin, BBQ sticks, and lilikoi pie.","price":"$"},{"name":"Bubba's Burgers","detail":"Koloa burger joint with local beef and the famous Bubba burger challenge.","price":"$"}],"rainyDay":["Kauai Museum (Lihue)","Grove Farm Museum","Koloa Rum Company tasting & tour"],"driveNotes":"Kauai is small but the single main road means the north and south shores are 2+ hours apart \u2014 pick one base. The north shore (Haena) needs advance parking reservations for Haena State Park. Book N\u0101 Pali boat tours ahead.","related":["oahu-hi-beach","maui-hi-beach","big-island-hi-adventure"],"imageAsset":"assets/pacific/images/kauai-hi-nature/hero.jpg"},{"id":"big-island-hi-adventure","title":"Big Island, HI: Four-Day Adventure","destination":"Big Island, HI","state":"HI","stateName":"Hawaii","region":"Island of Hawaii","days":4,"tripType":"adventure","interests":["family","outdoors","nature","scenic","beaches"],"budget":3600,"budgetNote":"Est. for 2 adults + 2 kids: 3 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"Walk on a volcano, stargaze from 13,800 feet, and swim at a black-sand beach \u2014 all in one island.","overview":"The Big Island is Hawaii's adventure capital: an active volcano you can walk across, the world's best stargazing mountain, 400-foot waterfalls, and beaches of black, green, and white sand. It's big \u2014 plan two bases (Kona side and volcano side) for four days. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk across the K\u012blauea Iki crater floor","Stargaze from Mauna Kea's 13,800-foot summit","Swim with manta rays on a night snorkel","Stand at the base of 442-foot 'Akaka Falls","Spot sea turtles at Punalu'u Black Sand Beach"],"bestSeason":"Year-round","familyFriendly":"Best for ages 7+. Volcano hikes and manta snorkels thrill older kids; Mauna Kea's altitude isn't for infants.","lat":19.64014,"lng":-155.99657,"itinerary":[{"day":1,"title":"Volcanoes National Park","morning":{"stop":"K\u012blauea Iki Overlook & hike","description":"Descend into the K\u012blauea Iki crater on the 3.3-mile loop \u2014 walking across a solidified lava lake with steam vents is otherworldly. Start early; the crater floor heats up.","cost":"$30/vehicle park entry (est.)","time":"8:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Chain of Craters Road","description":"Drive the 20-mile road down to the sea, stopping at craters, lava tubes (N\u0101huku/Thurston), and the Holei Sea Arch. The landscape changes from rainforest to raw lava.","cost":"Included with entry (est.)","time":"1:30 PM \u2013 5:30 PM"},"evening":{"stop":"Volcano Village dinner","description":"Dinner in Volcano Village \u2014 cozy restaurants in the rainforest. If the volcano is erupting, return to the park after dark for the glow.","cost":"$55\u2013$80 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Waterfalls & Turtles","morning":{"stop":"'Akaka Falls State Park","description":"A 0.4-mile loop through ginger and bamboo to the 442-foot 'Akaka Falls \u2014 Hawaii's most famous waterfall. Easy, paved, done in an hour.","cost":"$10 parking (est.)","time":"9:00 AM \u2013 11:00 AM"},"afternoon":{"stop":"Hilo & lunch","description":"Lunch in Hilo \u2014 the farmers market and Two Ladies Kitchen mochi. Visit the free Pana'ewa Rainforest Zoo (the only tropical zoo in the U.S.).","cost":"$40\u2013$60 for lunch (est.)","time":"11:30 AM \u2013 3:00 PM"},"evening":{"stop":"Punalu'u Black Sand Beach","description":"Drive the south route to Punalu'u \u2014 jet-black sand and basking green sea turtles. Swim carefully; the water is cool from freshwater springs.","cost":"Free (est.)","time":"3:30 PM \u2013 6:00 PM"}},{"day":3,"title":"Mauna Kea","morning":{"stop":"Kona coffee morning","description":"Tour a Kona coffee farm \u2014 free tastings, and kids love the roasting demo. Then drive to Waikoloa for lunch and a beach break.","cost":"Free tours (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Mauna Kea ascent","description":"Drive to the 9,200-foot visitor station for sunset \u2014 acclimate, watch the sun drop below the clouds, then join the free stargazing program with telescopes.","cost":"Free (est.)","time":"3:00 PM \u2013 8:00 PM"},"evening":{"stop":"Summit stargazing","description":"If your vehicle is 4WD (required for the summit road), continue to 13,800 feet for the darkest skies in America. Otherwise the visitor station's program is spectacular on its own.","cost":"Free (est.)","time":"8:00 PM \u2013 10:00 PM"}},{"day":4,"title":"Manta Rays & Farewell","morning":{"stop":"Kona beach morning","description":"Slow morning at a Kona beach \u2014 Kahalu'u's turtle-filled snorkeling or Magic Sands' play waves. Last shave ice.","cost":"Free (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Pu'uhonua o H\u014dnaunau","description":"Visit the Place of Refuge \u2014 royal grounds, ki'i statues, and sea turtles on the black-lava shore. Deeply peaceful and culturally rich.","cost":"$20/vehicle (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Manta ray night snorkel","description":"The grand finale: float at night while giant manta rays barrel-roll inches below you, feeding on plankton in the lights. Unforgettable for ages 8+.","cost":"$130/adult, $100/child (est.)","time":"6:30 PM \u2013 9:00 PM"}}],"attractions":[{"name":"Hawai'i Volcanoes National Park","description":"Walk across the K\u012blauea Iki lava lake, peer into steam vents, and drive the Chain of Craters Road to the sea. When K\u012blauea erupts, the nighttime glow is unreal.","officialUrl":"https://www.nps.gov/havo","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hawai%27i+Volcanoes+National+Park+Volcano+HI","price":"$30/vehicle (est.)","photos":["assets/pacific/images/big-island-hi-adventure/attr1-1.jpg","assets/pacific/images/big-island-hi-adventure/attr1-2.jpg","assets/pacific/images/big-island-hi-adventure/attr1-3.jpg","assets/pacific/images/big-island-hi-adventure/attr1-4.jpg"]},{"name":"Mauna Kea","description":"At 13,800 feet, the world's premier stargazing mountain \u2014 above 40% of the atmosphere. The visitor station's free nightly stargazing program needs no 4WD; the summit does.","officialUrl":"https://hilo.hawaii.edu/maunakea/visitor-information/","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mauna+Kea+Hilo+HI","price":"Free (est.)","photos":["assets/pacific/images/big-island-hi-adventure/attr2-1.jpg","assets/pacific/images/big-island-hi-adventure/attr2-2.jpg","assets/pacific/images/big-island-hi-adventure/attr2-3.jpg","assets/pacific/images/big-island-hi-adventure/attr2-4.jpg"]},{"name":"'Akaka Falls State Park","description":"A 0.4-mile paved loop through tropical jungle to 442-foot 'Akaka Falls and 400-foot Kahuna Falls. The easiest big waterfall payoff in Hawaii.","officialUrl":"https://dlnr.hawaii.gov/dsp/parks/hawaii/akaka-falls-state-park","mapsUrl":"https://www.google.com/maps/search/?api=1&query=%27Akaka+Falls+State+Park+Honomu+HI","price":"$10 parking (est.)","photos":["assets/pacific/images/big-island-hi-adventure/attr3-1.jpg","assets/pacific/images/big-island-hi-adventure/attr3-2.jpg","assets/pacific/images/big-island-hi-adventure/attr3-3.jpg","assets/pacific/images/big-island-hi-adventure/attr3-4.jpg"]},{"name":"Punalu'u Black Sand Beach","description":"Jet-black sand, swaying palms, and endangered green sea turtles hauled out to bask. The contrast of black sand, blue water, and green turtles is pure Big Island.","officialUrl":"https://www.parks.hawaiicounty.gov/Home/Components/FacilityDirectory/FacilityDirectory/618/1912?npage=8","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Punalu%27u+Black+Sand+Beach+Pahala+HI","price":"Free (est.)","photos":["assets/pacific/images/big-island-hi-adventure/attr4-1.jpg","assets/pacific/images/big-island-hi-adventure/attr4-2.jpg","assets/pacific/images/big-island-hi-adventure/attr4-3.jpg","assets/pacific/images/big-island-hi-adventure/attr4-4.jpg"]}],"restaurants":[{"name":"Pineapples Island Fresh Cuisine","detail":"Open-air Hilo favorite \u2014 island fish tacos and live music.","price":"$$"},{"name":"Tex Drive-In","detail":"Honoka'a institution \u2014 hot malasadas and plate lunches on the Hamakua Coast.","price":"$"},{"name":"Huggo's","detail":"Kona waterfront classic \u2014 sunset views and the famous mai tais.","price":"$$"}],"rainyDay":["'Imiloa Astronomy Center (Hilo)","Pacific Tsunami Museum (Hilo)","Kona coffee farm tours (covered)"],"driveNotes":"The island is BIG \u2014 Kona to Volcano is 2.5 hours. Split your stay: 2 nights Kona side, 1\u20132 nights Volcano side. Mauna Kea's summit road requires 4WD and the altitude (13,800 ft) demands acclimatizing; kids under 13 are discouraged at the summit.","related":["maui-hi-beach","kauai-hi-nature","oahu-hi-beach"],"imageAsset":"assets/pacific/images/big-island-hi-adventure/hero.jpg"},{"id":"lanai-hi-island","title":"Lanai, HI: Three-Day Island Escape","destination":"Lanai, HI","state":"HI","stateName":"Hawaii","region":"Lanai","days":3,"tripType":"island escape","interests":["family","beaches","nature","scenic"],"budget":3200,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights island hotel, meals, ferry from Maui, and activities.","tagline":"Hawaii's most secluded island \u2014 empty beaches, a Martian garden, and 600 rescue cats.","overview":"Lanai is the Hawaii of fifty years ago: 3,000 residents, no traffic lights, and beaches you'll share with no one. Snorkel Hulopo'e Bay's marine preserve, wander the Mars-like Garden of the Gods, and let the kids play with 600 rescue cats. It's a splurge \u2014 and worth it. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Snorkel the marine preserve at Hulopo'e Bay","Wander the red-rock Garden of the Gods","Cuddle 600 rescue cats at the Cat Sanctuary","Beachcomb Shipwreck Beach's ghostly shoreline","Stroll plantation-era Lanai City"],"bestSeason":"Year-round","familyFriendly":"Best for all ages. Hulopo'e Bay is calm and protected; the island's slow pace suits young kids perfectly.","lat":20.82794,"lng":-156.91952,"itinerary":[{"day":1,"title":"Arrival & Hulopo'e Bay","morning":{"stop":"Ferry from Maui","description":"Sail from Lahaina (45 minutes) \u2014 dolphins often escort the boat. Shuttle to Lanai City, check in, and feel the island slow down.","cost":"Ferry $30/adult, $20/child (est.)","time":"9:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Hulopo'e Bay","description":"The island's best beach: a protected marine preserve with calm snorkeling, tide pools, and spinner dolphins offshore. Picnic under the pines.","cost":"Free (est.)","time":"1:00 PM \u2013 5:00 PM"},"evening":{"stop":"Lanai City dinner","description":"Dinner in plantation-era Lanai City \u2014 the town square's cook pines are lit at night. Small-town quiet.","cost":"$60\u2013$90 for dinner (est.)","time":"6:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Garden of the Gods & Cats","morning":{"stop":"Garden of the Gods","description":"Drive the red-dirt Munro Trail to Keahiakawelo \u2014 a Martian landscape of red rock towers and spires. Sunrise or sunset light is best; bring water, there's no shade.","cost":"Free (4WD recommended) (est.)","time":"8:30 AM \u2013 11:30 AM"},"afternoon":{"stop":"Lanai Cat Sanctuary","description":"Visit 600 rescue cats roaming 3.5 acres \u2014 the kids' undisputed highlight. The 'furry purry' hour lets you brush and play with them.","cost":"Free; donations welcome (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Lanai City evening","description":"Explore the shops and galleries around Dole Park. Casual dinner \u2014 the island's pace makes every meal feel unhurried.","cost":"$55\u2013$85 for dinner (est.)","time":"4:30 PM \u2013 7:30 PM"}},{"day":3,"title":"Shipwreck Beach & Farewell","morning":{"stop":"Shipwreck Beach","description":"Drive the north shore to Kaiolohia \u2014 the rusting WWII liberty ship on the reef, tide pools, and excellent beachcombing. Watch for monk seals.","cost":"Free (est.)","time":"9:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Sweetheart Rock","description":"Walk the coastal trail from Hulopo'e to Pu'u Pehe (Sweetheart Rock) \u2014 the sea stack with a Hawaiian legend. Last swim at the bay.","cost":"Free (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Ferry back","description":"Late-afternoon ferry to Maui. Watch Lanai fade into the sunset \u2014 and start planning your return.","cost":"Included in round trip (est.)","time":"4:30 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Hulopo'e Bay","description":"Lanai's premier beach: a marine life conservation district with calm, clear snorkeling, tide pools, and frequent spinner dolphin visits. The coastal trail to Sweetheart Rock starts here.","officialUrl":"https://www.gohawaii.com/islands/lanai/regions/south-lanai/hulopoe-bay","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hulopo%27e+Bay+Lanai+City+HI","price":"Free (est.)","photos":["assets/pacific/images/lanai-hi-island/attr1-1.jpg","assets/pacific/images/lanai-hi-island/attr1-2.jpg","assets/pacific/images/lanai-hi-island/attr1-3.jpg","assets/pacific/images/lanai-hi-island/attr1-4.jpg"]},{"name":"Garden of the Gods","description":"Keahiakawelo: a windswept plateau of red, orange, and purple rock formations that looks like Mars. Best at sunrise or sunset; a 4WD helps on the Munro Trail.","officialUrl":"https://www.gohawaii.com/islands/lanai/regions/north-lanai/keahiakawelo","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Garden+of+the+Gods+Lanai+City+HI","price":"Free (est.)","photos":["assets/pacific/images/lanai-hi-island/attr2-1.jpg","assets/pacific/images/lanai-hi-island/attr2-2.jpg","assets/pacific/images/lanai-hi-island/attr2-3.jpg","assets/pacific/images/lanai-hi-island/attr2-4.jpg"]},{"name":"Lanai Cat Sanctuary","description":"Home to 600 rescued cats on 3.5 acres \u2014 one of Hawaii's most beloved animal sanctuaries. Visitors can cuddle, brush, and play with the residents; adoption possible.","officialUrl":"https://www.lanaicatsanctuary.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lanai+Cat+Sanctuary+Lanai+City+HI","price":"Free; donations welcome (est.)","photos":["assets/pacific/images/lanai-hi-island/attr3-1.jpg","assets/pacific/images/lanai-hi-island/attr3-2.jpg","assets/pacific/images/lanai-hi-island/attr3-3.jpg","assets/pacific/images/lanai-hi-island/attr3-4.jpg"]},{"name":"Shipwreck Beach","description":"Kaiolohia: eight miles of north-shore beach named for the rusting WWII ship on its reef. Superb beachcombing, tide pools, and seasonal whale watching from shore.","officialUrl":"https://www.gohawaii.com/islands/lanai/regions/north-lanai/kaiolohia","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Shipwreck+Beach+Lanai+City+HI","price":"Free (est.)","photos":["assets/pacific/images/lanai-hi-island/attr4-1.jpg","assets/pacific/images/lanai-hi-island/attr4-2.jpg","assets/pacific/images/lanai-hi-island/attr4-3.jpg","assets/pacific/images/lanai-hi-island/attr4-4.jpg"]}],"restaurants":[{"name":"Nobu Lanai","detail":"World-famous Japanese-Peruvian at the Four Seasons \u2014 the splurge dinner.","price":"$$$"},{"name":"Blue Ginger Caf\u00e9","detail":"Lanai City local favorite \u2014 loco moco and plate lunches done right.","price":"$"},{"name":"Lanai City Bar & Grille","detail":"Upscale island dining in the historic Hotel Lanai \u2014 fresh fish, venison, and live music on weekends.","price":"$$$"}],"rainyDay":["Lanai Culture & Heritage Center","Mike Carroll Gallery (local art)","Hotel pool & game room day"],"driveNotes":"Most visitors arrive by ferry from Lahaina, Maui (45 min) \u2014 no car needed if you stay in Lanai City and use hotel shuttles. To explore the Garden of the Gods and Shipwreck Beach, rent a 4WD jeep on the island. There are only 30 miles of paved road.","related":["maui-hi-beach","kauai-hi-nature","oahu-hi-beach"],"imageAsset":"assets/pacific/images/lanai-hi-island/hero.jpg"},{"id":"anchorage-ak-city","title":"Anchorage, AK: Three-Day City Adventure","destination":"Anchorage, AK","state":"AK","stateName":"Alaska","region":"Southcentral Alaska","days":3,"tripType":"city adventure","interests":["family","outdoors","nature","museums","scenic"],"budget":2200,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"Moose on the bike trail, glaciers at the doorstep, and midnight sun in summer.","overview":"Anchorage is Alaska's urban basecamp \u2014 a real city where moose wander the bike trails and the mountains start at the city limits. Ride the coastal trail, dive into Alaska Native cultures, and meet rescued wildlife, all without leaving the metro area. It's the perfect soft landing for an Alaska family trip. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Bike the 11-mile Tony Knowles Coastal Trail","Watch Native dance at the Alaska Native Heritage Center","Meet rescued moose and bears at the Wildlife Conservation Center","Explore the Smithsonian Arctic collection at the Anchorage Museum","Day-trip to the Portage Glacier"],"bestSeason":"May\u2013September","familyFriendly":"Best for all ages. Flat coastal trail suits bikes and strollers; summer's midnight sun keeps kids playing late.","lat":61.21752,"lng":-149.85815,"itinerary":[{"day":1,"title":"Coastal Trail & Downtown","morning":{"stop":"Tony Knowles Coastal Trail","description":"Rent bikes downtown and ride the 11-mile paved trail along Cook Inlet \u2014 mountain views, possible moose, and beluga whales in summer. Ride as far as the kids want; it's an out-and-back.","cost":"Bike rental ~$25/person (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Downtown & lunch","description":"Lunch downtown \u2014 reindeer sausage from a street cart is the classic. Browse the Saturday Market (summer weekends) for Native crafts.","cost":"$45\u2013$65 for lunch (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Earthquake Park sunset","description":"Walk Earthquake Park's interpretive trail \u2014 the land dropped 8 feet in the 1964 quake. Sunset over the inlet with the Alaska Range beyond.","cost":"Free (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Culture & Wildlife","morning":{"stop":"Alaska Native Heritage Center","description":"Watch Native dance performances, tour the six traditional dwellings around the lake, and try the hands-on crafts. The storytelling sessions captivate kids.","cost":"$30/adult, $20/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Anchorage Museum","description":"The Smithsonian Arctic Studies Center's 600+ Native artifacts, the Imaginarium kids' discovery center, and the planetarium \u2014 a full afternoon indoors.","cost":"$20/adult, $12/child (est.)","time":"1:30 PM \u2013 5:00 PM"},"evening":{"stop":"Downtown dinner","description":"Dinner downtown \u2014 Alaska seafood and brewpub fare. Summer evenings stay light until nearly midnight.","cost":"$60\u2013$90 for dinner (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Glaciers & Wildlife","morning":{"stop":"Alaska Wildlife Conservation Center","description":"Drive 45 minutes to Portage to meet rescued moose, bears, caribou, and musk oxen \u2014 all in natural habitats. The 1.5-mile loop is drivable or walkable.","cost":"$20/adult, $13/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Portage Glacier","description":"Continue to Portage Glacier \u2014 take the one-hour lake cruise to the glacier's face (icebergs included) or walk the Byron Glacier trail.","cost":"Cruise $45/adult, $25/child (est.)","time":"1:30 PM \u2013 5:00 PM"},"evening":{"stop":"Farewell along Turnagain Arm","description":"Drive back along the stunning Turnagain Arm \u2014 watch for belugas and Dall sheep. Dinner in Girdwood on the way.","cost":"$55\u2013$85 for dinner (est.)","time":"5:30 PM \u2013 8:30 PM"}}],"attractions":[{"name":"Tony Knowles Coastal Trail","description":"Eleven miles of paved waterfront trail from downtown to Kincaid Park, with Cook Inlet, the Alaska Range, and frequent moose. Bike rentals downtown make it easy.","officialUrl":"https://www.muni.org/Departments/parks/Pages/default.aspx","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tony+Knowles+Coastal+Trail+Anchorage+AK","price":"Free; rentals ~$25 (est.)","photos":["assets/pacific/images/anchorage-ak-city/attr1-1.jpg","assets/pacific/images/anchorage-ak-city/attr1-2.jpg","assets/pacific/images/anchorage-ak-city/attr1-3.jpg","assets/pacific/images/anchorage-ak-city/attr1-4.jpg"]},{"name":"Alaska Native Heritage Center","description":"Celebrate Alaska's 11 Native cultures: dance performances, six life-size traditional dwellings, storytelling, and hands-on art. The lake setting is beautiful.","officialUrl":"https://www.alaskanative.net","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Alaska+Native+Heritage+Center+Anchorage+AK","price":"$30/adult, $20/child (est.)","photos":["assets/pacific/images/anchorage-ak-city/attr2-1.jpg","assets/pacific/images/anchorage-ak-city/attr2-2.jpg","assets/pacific/images/anchorage-ak-city/attr2-3.jpg","assets/pacific/images/anchorage-ak-city/attr2-4.jpg"]},{"name":"Anchorage Museum","description":"Alaska's largest museum: the Smithsonian Arctic Studies Center, the Imaginarium children's discovery center, and a planetarium. The Alaska gallery tells the state's story brilliantly.","officialUrl":"https://www.anchoragemuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Anchorage+Museum+Anchorage+AK","price":"$20/adult, $12/child (est.)","photos":["assets/pacific/images/anchorage-ak-city/attr3-1.jpg","assets/pacific/images/anchorage-ak-city/attr3-2.jpg","assets/pacific/images/anchorage-ak-city/attr3-3.jpg","assets/pacific/images/anchorage-ak-city/attr3-4.jpg"]},{"name":"Alaska Wildlife Conservation Center","description":"A 200-acre refuge for orphaned and injured animals: brown and black bears, moose, caribou, musk oxen, and eagles \u2014 all in spacious natural habitats near Portage.","officialUrl":"https://www.alaskawildlife.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Alaska+Wildlife+Conservation+Center+Girdwood+AK","price":"$20/adult, $13/child (est.)","photos":["assets/pacific/images/anchorage-ak-city/attr4-1.jpg","assets/pacific/images/anchorage-ak-city/attr4-2.jpg","assets/pacific/images/anchorage-ak-city/attr4-3.jpg","assets/pacific/images/anchorage-ak-city/attr4-4.jpg"]}],"restaurants":[{"name":"49th State Brewing","detail":"Downtown brewpub with yak burgers, a rooftop deck, and family-friendly bustle.","price":"$$"},{"name":"Moose's Tooth Pub & Pizzeria","detail":"Anchorage's beloved pizza joint \u2014 creative pies, fast, loud, fun.","price":"$"},{"name":"Simon & Seafort's","detail":"Upscale waterfront seafood with Cook Inlet views \u2014 the special-occasion pick.","price":"$$$"}],"rainyDay":["Anchorage Museum (all indoors)","Alaska Native Heritage Center (performances indoors)","H2Oasis Indoor Waterpark"],"driveNotes":"Anchorage is car-friendly with easy parking. Summer brings the midnight sun (19+ hours of daylight) \u2014 bring sleep masks. The Seward Highway to Portage and Girdwood is stunning but can be slow; allow extra time. Book summer lodging early.","related":["denali-ak-nature","seward-ak-coast","juneau-ak-city"],"imageAsset":"assets/pacific/images/anchorage-ak-city/hero.jpg"},{"id":"denali-ak-nature","title":"Denali, AK: Three-Day Nature Escape","destination":"Denali, AK","state":"AK","stateName":"Alaska","region":"Interior Alaska","days":3,"tripType":"nature escape","interests":["family","outdoors","nature","scenic"],"budget":2000,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights park-area lodge, meals, bus tour, and park entry.","tagline":"North America's tallest peak, grizzlies on the tundra, and a road where the bus is the only way in.","overview":"Denali is Alaska's crown jewel: six million acres of wilderness, one 92-mile road, and wildlife that shows up like clockwork. The narrated bus tour into the park is the essential experience \u2014 grizzlies, caribou, Dall sheep, and maybe the mountain itself, which hides in clouds 70% of the time. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Spot grizzlies and caribou on the park road bus tour","See 20,310-foot Denali (if the clouds part!)","Meet the husky teams at the sled dog kennels","Hike the tundra at Savage River","Pan for gold like the 1900s stampeders"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 7+. The bus tour is 6\u201312 hours \u2014 the shorter 4\u20135 hour Savage River tour suits younger kids.","lat":63.73183,"lng":-148.89198,"itinerary":[{"day":1,"title":"Arrival & Kennels","morning":{"stop":"Denali Visitor Center","description":"Start at the visitor center \u2014 exhibits, the park film, and Junior Ranger badges. Book bus tours here if you haven't.","cost":"$15/person park entry (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Sled dog kennels","description":"Meet the husky teams that patrol the park in winter \u2014 ranger demos with the dogs running, plus puppy time in summer. Kids' favorite.","cost":"Free (est.)","time":"1:00 PM \u2013 3:00 PM"},"evening":{"stop":"Savage River evening","description":"Drive the 15 miles of private-vehicle road to Savage River. Walk the 2-mile loop along the river \u2014 caribou often graze nearby. Dinner at the park entrance area.","cost":"$50\u2013$75 for dinner (est.)","time":"4:00 PM \u2013 8:00 PM"}},{"day":2,"title":"The Bus Tour","morning":{"stop":"Tundra Wilderness Tour","description":"The big day: a 5\u20136 hour narrated bus tour to mile 43. The driver-guide spots wildlife you'd never see \u2014 grizzlies, moose, caribou, Dall sheep. Bring snacks, layers, and binoculars.","cost":"$130/adult, $65/child (est.)","time":"7:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Rest & visitor campus","description":"Recover at the lodge \u2014 the morning starts early. Afternoon at the visitor campus: the bookstore, the sled dog demo (second showing), or just tundra views.","cost":"Free (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Dinner theater","description":"Dinner and the Denali Dinner Theater or a ranger evening program. Early bed \u2014 Alaska summer light makes bedtime tricky; bring masks.","cost":"$60\u2013$90 for dinner (est.)","time":"6:00 PM \u2013 9:00 PM"}},{"day":3,"title":"Trails & Farewell","morning":{"stop":"Horseshoe Lake Trail","description":"An easy 2-mile loop near the entrance: beaver dams, a lake reflecting the peaks, and good moose odds. Perfect final hike.","cost":"Free (est.)","time":"9:00 AM \u2013 11:30 AM"},"afternoon":{"stop":"Gold panning & lunch","description":"Try panning for gold at the area's historic claims \u2014 kids keep what they find (usually a few flakes). Lunch at a park-entrance caf\u00e9.","cost":"Panning $20/person (est.)","time":"12:00 PM \u2013 3:00 PM"},"evening":{"stop":"Farewell views","description":"One last scan for the mountain from the overlooks. If Denali showed itself, you beat the 30% odds \u2014 buy the t-shirt. Dinner before the drive.","cost":"$50\u2013$75 for dinner (est.)","time":"3:30 PM \u2013 6:00 PM"}}],"attractions":[{"name":"Denali Park Road Bus Tour","description":"Private cars stop at mile 15 \u2014 beyond that, only park buses go. The narrated Tundra Wilderness Tour (mile 43) is the classic: 5\u20136 hours of grizzlies, caribou, and the mountain.","officialUrl":"https://www.nps.gov/dena","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Denali+Park+Road+Bus+Tour+Denali+National+Park+AK","price":"$130/adult, $65/child (est.)","photos":["assets/pacific/images/denali-ak-nature/attr1-1.jpg","assets/pacific/images/denali-ak-nature/attr1-2.jpg","assets/pacific/images/denali-ak-nature/attr1-3.jpg","assets/pacific/images/denali-ak-nature/attr1-4.jpg"]},{"name":"Denali Sled Dog Kennels","description":"The park's working husky teams \u2014 the only sled dogs in the National Park System. Summer ranger demos show the dogs running, with puppy petting after.","officialUrl":"https://www.nps.gov/dena","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Denali+Sled+Dog+Kennels+Denali+National+Park+AK","price":"Free (est.)","photos":["assets/pacific/images/denali-ak-nature/attr2-1.jpg","assets/pacific/images/denali-ak-nature/attr2-2.jpg","assets/pacific/images/denali-ak-nature/attr2-3.jpg","assets/pacific/images/denali-ak-nature/attr2-4.jpg"]},{"name":"Savage River","description":"Mile 15 \u2014 as far as private cars go. The 2-mile loop trail follows the braided river through tundra with caribou, grizzlies (at a distance), and big mountain views.","officialUrl":"https://www.nps.gov/dena","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Savage+River+Denali+National+Park+AK","price":"Included with entry (est.)","photos":["assets/pacific/images/denali-ak-nature/attr3-1.jpg","assets/pacific/images/denali-ak-nature/attr3-2.jpg","assets/pacific/images/denali-ak-nature/attr3-3.jpg","assets/pacific/images/denali-ak-nature/attr3-4.jpg"]},{"name":"Denali Visitor Center","description":"The park's hub: exhibits on the mountain and wildlife, the park film, backcountry info, and the Junior Ranger program. Start every visit here.","officialUrl":"https://www.nps.gov/dena","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Denali+Visitor+Center+Denali+National+Park+AK","price":"$15/person entry (est.)","photos":["assets/pacific/images/denali-ak-nature/attr4-1.jpg","assets/pacific/images/denali-ak-nature/attr4-2.jpg","assets/pacific/images/denali-ak-nature/attr4-3.jpg","assets/pacific/images/denali-ak-nature/attr4-4.jpg"]}],"restaurants":[{"name":"Prospector's Pizzeria & Alehouse","detail":"Hearty pizza and local brews in a gold-rush-themed hall near the park entrance.","price":"$$"},{"name":"Denali Park Salmon Bake","detail":"All-you-can-eat Alaskan salmon bake \u2014 fun, filling, and outdoorsy.","price":"$$"},{"name":"McKinley Creekside Caf\u00e9","detail":"Cozy caf\u00e9 south of the park with great breakfasts and homemade pie.","price":"$"}],"rainyDay":["Denali Visitor Center (films & exhibits)","Murie Science and Learning Center","Denali Square (shops & presentations)"],"driveNotes":"Denali is 4 hours north of Anchorage on the Parks Highway \u2014 a beautiful drive. Book bus tours and lodging months ahead; summer sells out. Weather is unpredictable: pack rain gear and warm layers even in July. The mountain is visible only ~30% of the time.","related":["anchorage-ak-city","fairbanks-ak-city","seward-ak-coast"],"imageAsset":"assets/pacific/images/denali-ak-nature/hero.jpg"},{"id":"juneau-ak-city","title":"Juneau, AK: Three-Day City Adventure","destination":"Juneau, AK","state":"AK","stateName":"Alaska","region":"Southeast Alaska","days":3,"tripType":"city adventure","interests":["family","outdoors","nature","scenic","historical-sites"],"budget":2400,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights downtown hotel, meals, tours, and attraction tickets.","tagline":"A capital city with a glacier in its backyard and whales in its front yard.","overview":"Juneau is unreachable by road \u2014 you fly or sail in \u2014 and that's the point. The Mendenhall Glacier spills to a lake 20 minutes from downtown, humpbacks feed in the channel all summer, and the Mt. Roberts Tramway lifts you 1,800 feet for the overview. Three days of Alaska at its most accessible. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk to the face of the Mendenhall Glacier","Watch humpbacks bubble-net feeding on a whale tour","Ride the Mt. Roberts Tramway for the city panorama","See a 40-foot totem wall at the Alaska State Museum","Pan for gold at the historic Last Chance Basin"],"bestSeason":"May\u2013September","familyFriendly":"Best for ages 6+. Glacier trails are easy; whale tours suit kids who handle 3 hours on the water.","lat":58.29973,"lng":-134.40679,"itinerary":[{"day":1,"title":"Mendenhall Glacier","morning":{"stop":"Mendenhall Glacier Visitor Center","description":"Drive 20 minutes to the glacier \u2014 the 1-mile Nugget Falls trail leads to a thundering waterfall with the blue ice behind it. The visitor center's exhibits explain the retreating ice.","cost":"$5/person (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Glacier trails & lunch","description":"Walk the Photo Point trail for the classic glacier-lake view, then lunch back downtown. The salmon bake at the glacier is a fun option.","cost":"$45\u2013$65 for lunch (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Downtown & tram","description":"Ride the Mt. Roberts Tramway 1,800 feet up for the evening panorama \u2014 Gastineau Channel, Douglas Island, and the icefield. Dinner downtown after.","cost":"Tram $38/adult, $24/child (est.)","time":"5:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Whales & Culture","morning":{"stop":"Whale watching tour","description":"Sail Auke Bay with a naturalist \u2014 humpbacks bubble-net feed here all summer, plus orcas, sea lions, and eagles. Most tours guarantee sightings.","cost":"$180/adult, $120/child (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Alaska State Museum","description":"The stunning museum's 40-foot totem wall, eagle-tree artifacts, and gold-rush exhibits tell Alaska's story. The kids' discovery drawers are a hit.","cost":"$14/adult, kids free (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Downtown dinner","description":"Dinner downtown \u2014 king crab legs are the splurge. Stroll the waterfront and the historic district's colorful storefronts.","cost":"$70\u2013$110 for dinner (est.)","time":"5:00 PM \u2013 8:30 PM"}},{"day":3,"title":"Gold & Farewell","morning":{"stop":"Last Chance Basin","description":"Pan for gold where Joe Juneau struck it rich in 1880 \u2014 guided panning tours guarantee flakes. Hike the Perseverance Trail's waterfalls if energy allows.","cost":"Panning $35/person (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Glacier Gardens","description":"Tour the rainforest botanical garden \u2014 upside-down flower towers in the treetops, reached by golf cart. Lunch at the glacier-view caf\u00e9.","cost":"$30/adult, $18/child (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell waterfront","description":"Final stroll on the waterfront seawalk \u2014 watch floatplanes take off. Farewell dinner downtown.","cost":"$60\u2013$90 for dinner (est.)","time":"4:30 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Mendenhall Glacier","description":"A 13-mile river of blue ice ending in a lake 20 minutes from downtown. Walk to Nugget Falls, explore the visitor center, and watch for black bears fishing the salmon streams.","officialUrl":"https://www.fs.usda.gov/recarea/tongass/recarea/?recid=78634","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mendenhall+Glacier+Juneau+AK","price":"$5/person (est.)","photos":["assets/pacific/images/juneau-ak-city/attr1-1.jpg","assets/pacific/images/juneau-ak-city/attr1-2.jpg","assets/pacific/images/juneau-ak-city/attr1-3.jpg","assets/pacific/images/juneau-ak-city/attr1-4.jpg"]},{"name":"Mount Roberts Tramway","description":"Ride 1,800 feet straight up from the cruise docks to alpine trails, a nature center, and the best panorama in Juneau. The mountaintop eagle and raven show delights kids.","officialUrl":"https://www.mountrobertstramway.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mount+Roberts+Tramway+Juneau+AK","price":"$38/adult, $24/child (est.)","photos":["assets/pacific/images/juneau-ak-city/attr2-1.jpg","assets/pacific/images/juneau-ak-city/attr2-2.jpg","assets/pacific/images/juneau-ak-city/attr2-3.jpg","assets/pacific/images/juneau-ak-city/attr2-4.jpg"]},{"name":"Alaska State Museum","description":"Alaska's story in one stunning building: a 40-foot indoor totem wall, 2,000-year-old artifacts, and gold-rush history. Free for kids 18 and under.","officialUrl":"https://museums.alaska.gov/asm/","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Alaska+State+Museum+Juneau+AK","price":"$14/adult, kids free (est.)","photos":["assets/pacific/images/juneau-ak-city/attr3-1.jpg","assets/pacific/images/juneau-ak-city/attr3-2.jpg","assets/pacific/images/juneau-ak-city/attr3-3.jpg","assets/pacific/images/juneau-ak-city/attr3-4.jpg"]},{"name":"Juneau Whale Watching","description":"Auke Bay's humpbacks bubble-net feed all summer \u2014 one of the world's most reliable whale shows. Tours run 3\u20134 hours with naturalists and sighting guarantees.","officialUrl":"https://www.juneauwhalewatch.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Juneau+Whale+Watching+Juneau+AK","price":"$180/adult, $120/child (est.)","photos":["assets/pacific/images/juneau-ak-city/attr4-1.jpg","assets/pacific/images/juneau-ak-city/attr4-2.jpg","assets/pacific/images/juneau-ak-city/attr4-3.jpg","assets/pacific/images/juneau-ak-city/attr4-4.jpg"]}],"restaurants":[{"name":"Tracy's King Crab Shack","detail":"The famous waterfront shack \u2014 giant crab legs and crab bisque, worth the line.","price":"$$$"},{"name":"The Hangar on the Wharf","detail":"Waterfront restaurant in a 1930s airplane hangar; great fish and kids' menu.","price":"$$"},{"name":"Deckhand Dave's","detail":"Food-truck-turned-local-legend for fish tacos on the docks.","price":"$"}],"rainyDay":["Alaska State Museum (indoors)","Juneau-Douglas City Museum","Mendenhall Glacier Visitor Center (exhibits)"],"driveNotes":"Juneau has no road access \u2014 fly in or take the Alaska Marine Highway ferry. Downtown is walkable; rent a car for the glacier and Auke Bay, or use the excellent tour shuttles. Summer cruise crowds peak midday \u2014 do the glacier early.","related":["anchorage-ak-city","seward-ak-coast","fairbanks-ak-city"],"imageAsset":"assets/pacific/images/juneau-ak-city/hero.jpg"},{"id":"fairbanks-ak-city","title":"Fairbanks, AK: Three-Day Northern Adventure","destination":"Fairbanks, AK","state":"AK","stateName":"Alaska","region":"Interior Alaska","days":3,"tripType":"northern adventure","interests":["family","outdoors","nature","museums","scenic"],"budget":2100,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, rental car, and attraction tickets.","tagline":"Hot springs under the northern lights, a world-class northern museum, and Santa's year-round workshop.","overview":"Fairbanks is Alaska's golden heart \u2014 a frontier city where you can soak in 106\u00b0F hot springs, tour a museum rivaling any in the West, and visit Santa's actual house (in North Pole, naturally). Summer brings the midnight sun; winter brings the aurora. Either way, it's unforgettable. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Soak in Chena's 106\u00b0F outdoor rock lake","Chase the aurora on a winter night tour","See Blue Babe the 36,000-year-old bison at the Museum of the North","Meet Santa's reindeer at the Santa Claus House","Pan for gold at Gold Dredge 8"],"bestSeason":"June\u2013August, December\u2013March","familyFriendly":"Best for all ages. The museum and Santa Claus House delight young kids; aurora viewing suits night-owl older kids.","lat":64.84527,"lng":-147.72213,"itinerary":[{"day":1,"title":"Museum & Downtown","morning":{"stop":"Museum of the North","description":"Start at the UA museum \u2014 Blue Babe the Ice Age bison, the 2,000-year-old ivory, and the aurora films. The family discovery room keeps young kids busy.","cost":"$16/adult, $9/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Downtown & lunch","description":"Lunch downtown, then the Morris Thompson Cultural Center's free exhibits and the historic district. Summer: the midnight-sun buzz is palpable.","cost":"$45\u2013$65 for lunch (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Creamer's Field","description":"Evening walk at Creamer's Field \u2014 the old dairy farm is now a migratory bird refuge. Sandhill cranes in spring, gorgeous light in summer.","cost":"Free (est.)","time":"5:00 PM \u2013 7:30 PM"}},{"day":2,"title":"Hot Springs Day","morning":{"stop":"Chena Hot Springs","description":"Drive 60 miles to Chena \u2014 soak in the 106\u00b0F outdoor rock lake surrounded by forest. Tour the Aurora Ice Museum's ice sculptures (martini glasses included for parents).","cost":"Soak $20/adult, $15/child (est.)","time":"10:00 AM \u2013 2:00 PM"},"afternoon":{"stop":"Ice Museum & lunch","description":"Lunch at the resort restaurant, then the geothermal energy tour \u2014 fascinating for science-loving kids. Keep swimsuits handy for a second soak.","cost":"$45\u2013$65 for lunch (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"Aurora watch (winter)","description":"In winter, stay for the evening aurora tour \u2014 heated yurts and expert guides. In summer, head back for midnight-sun mini golf instead.","cost":"Aurora tour $90/person (est.)","time":"8:00 PM \u2013 12:00 AM"}},{"day":3,"title":"North Pole & Gold","morning":{"stop":"Santa Claus House","description":"Drive 20 minutes to North Pole, Alaska \u2014 Santa's year-round workshop. Meet real reindeer, see the 42-foot Santa statue, and mail letters postmarked from the North Pole.","cost":"Free entry (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Gold Dredge 8","description":"Pan for gold at the historic dredge \u2014 everyone finds color, and kids keep their flakes. The narrated train ride explains the gold rush.","cost":"$40/adult, $25/child (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell dinner","description":"Final Fairbanks dinner \u2014 Thai, barbecue, or brewpub. If it's aurora season and the sky is clear, one last look up.","cost":"$55\u2013$80 for dinner (est.)","time":"5:00 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Chena Hot Springs Resort","description":"A geothermal oasis 60 miles from town: soak in the 106\u00b0F outdoor rock lake, tour the year-round Aurora Ice Museum, and \u2014 in winter \u2014 watch the northern lights from the hot water.","officialUrl":"https://www.chenahotsprings.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chena+Hot+Springs+Resort+Fairbanks+AK","price":"Soak $20/adult, $15/child (est.)","photos":["assets/pacific/images/fairbanks-ak-city/attr1-1.jpg","assets/pacific/images/fairbanks-ak-city/attr1-2.jpg","assets/pacific/images/fairbanks-ak-city/attr1-3.jpg","assets/pacific/images/fairbanks-ak-city/attr1-4.jpg"]},{"name":"UA Museum of the North","description":"Alaska's premier museum: Blue Babe the 36,000-year-old bison, Alaska Native art, and immersive aurora and landscape films. The family room is excellent for kids.","officialUrl":"https://www.uaf.edu/museum/","mapsUrl":"https://www.google.com/maps/search/?api=1&query=UA+Museum+of+the+North+Fairbanks+AK","price":"$16/adult, $9/child (est.)","photos":["assets/pacific/images/fairbanks-ak-city/attr2-1.jpg","assets/pacific/images/fairbanks-ak-city/attr2-2.jpg","assets/pacific/images/fairbanks-ak-city/attr2-3.jpg","assets/pacific/images/fairbanks-ak-city/attr2-4.jpg"]},{"name":"Santa Claus House","description":"In North Pole, Alaska: Santa's workshop, live reindeer, the world's largest Santa statue (42 feet), and letters postmarked from the North Pole. Christmas year-round.","officialUrl":"https://www.santaclaushouse.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Santa+Claus+House+North+Pole+AK","price":"Free entry (est.)","photos":["assets/pacific/images/fairbanks-ak-city/attr3-1.jpg","assets/pacific/images/fairbanks-ak-city/attr3-2.jpg","assets/pacific/images/fairbanks-ak-city/attr3-3.jpg","assets/pacific/images/fairbanks-ak-city/attr3-4.jpg"]},{"name":"Creamer's Field","description":"A 2,000-acre migratory waterfowl refuge on a historic dairy farm. Sandhill cranes and geese in migration seasons, boreal forest trails, and farm buildings to explore.","officialUrl":"https://www.adfg.alaska.gov/index.cfm?adfg=creamersfield.main","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Creamer%27s+Field+Fairbanks+AK","price":"Free (est.)","photos":["assets/pacific/images/fairbanks-ak-city/attr4-1.jpg","assets/pacific/images/fairbanks-ak-city/attr4-2.jpg","assets/pacific/images/fairbanks-ak-city/attr4-3.jpg","assets/pacific/images/fairbanks-ak-city/attr4-4.jpg"]}],"restaurants":[{"name":"The Cookie Jar Restaurant","detail":"Fairbanks comfort-food legend \u2014 huge cinnamon rolls and hearty breakfasts.","price":"$"},{"name":"Silver Gulch Brewing","detail":"America's northernmost brewery (in Fox) \u2014 great food and root beer for kids.","price":"$$"},{"name":"HooDoo Brewing Co.","detail":"Downtown brewery with excellent pub food and a family-friendly taproom.","price":"$$"}],"rainyDay":["Museum of the North (indoors)","Aurora Ice Museum (indoors, year-round)","Morris Thompson Cultural Center (free)"],"driveNotes":"Fairbanks is 6 hours north of Anchorage \u2014 fly or make it a road trip. Winter means -20\u00b0F cold: rent winter gear packages locally. Summer's midnight sun (21+ hours of daylight) needs sleep masks. Book aurora tours and Chena lodging ahead in winter.","related":["denali-ak-nature","anchorage-ak-city","juneau-ak-city"],"imageAsset":"assets/pacific/images/fairbanks-ak-city/hero.jpg"},{"id":"seward-ak-coast","title":"Seward, AK: Three-Day Coastal Adventure","destination":"Seward, AK","state":"AK","stateName":"Alaska","region":"Kenai Peninsula","days":3,"tripType":"coastal adventure","interests":["family","outdoors","nature","scenic","beaches"],"budget":2200,"budgetNote":"Est. for 2 adults + 2 kids: 2 nights mid-range hotel, meals, boat tour, and attraction tickets.","tagline":"Glaciers calving into the sea, puffins on the cliffs, and Alaska's prettiest harbor town.","overview":"Seward is where Alaska's mountains meet the sea \u2014 and the Kenai Fjords boat tour is the single best wildlife day trip in the state. Walk to a glacier's face at Exit Glacier, meet puffins and sea lions at the SeaLife Center, and wander a working harbor. Three perfect days. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Watch a glacier calve on a Kenai Fjords boat tour","Meet puffins and sea lions at the Alaska SeaLife Center","Walk to the face of Exit Glacier","Spot humpbacks and orcas in Resurrection Bay","Hike the coastal Tonsina Point trail"],"bestSeason":"May\u2013September","familyFriendly":"Best for ages 6+. Boat tours run 6\u20138 hours \u2014 the half-day Resurrection Bay tour suits younger kids.","lat":60.11235,"lng":-149.44294,"itinerary":[{"day":1,"title":"SeaLife Center & Harbor","morning":{"stop":"Alaska SeaLife Center","description":"Start at Alaska's only public aquarium: puffins diving, sea lions playing, and touch tanks with sea stars. The octopus and the seabird aviary are highlights.","cost":"$35/adult, $22/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Harbor & lunch","description":"Lunch on the harbor \u2014 watch fishing boats unload the day's catch. Walk the docks to spot sea otters and bald eagles.","cost":"$50\u2013$70 for lunch (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Tonsina Point trail","description":"An easy 2-mile coastal hike through rainforest to a secluded beach. Evening light on Resurrection Bay is gorgeous.","cost":"Free (est.)","time":"5:00 PM \u2013 7:30 PM"}},{"day":2,"title":"Kenai Fjords Boat Tour","morning":{"stop":"Full-day Kenai Fjords tour","description":"The essential Alaska day: 6\u20138 hours among tidewater glaciers, with humpbacks, orcas, puffins, sea lions, and eagles. The captain narrates; the glacier calving steals the show.","cost":"$220/adult, $110/child (est.)","time":"8:00 AM \u2013 4:00 PM"},"afternoon":{"stop":"Rest & hot tub","description":"Recover at the hotel \u2014 it's a long, glorious day. Let the kids swim while you thaw.","cost":"Free (est.)","time":"4:30 PM \u2013 6:00 PM"},"evening":{"stop":"Harbor dinner","description":"Dinner on the water \u2014 fresh halibut and king crab. Walk the harbor as the boats come in.","cost":"$70\u2013$110 for dinner (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":3,"title":"Exit Glacier & Farewell","morning":{"stop":"Exit Glacier","description":"Drive 15 minutes to the park's only road-accessible glacier. The 1-mile Glacier View Loop leads to the outwash plain; the 2.2-mile Harding Icefield trailhead climb is for strong hikers.","cost":"Free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Lunch & Two Lakes Trail","description":"Lunch back in town, then the easy Two Lakes Trail near the SeaLife Center \u2014 beaver dams and salmon streams.","cost":"$45\u2013$65 for lunch (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell along the bay","description":"Final waterfront stroll \u2014 the sea otter raft near the harbor is a perfect goodbye. Dinner before the drive back to Anchorage.","cost":"$55\u2013$80 for dinner (est.)","time":"4:30 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Kenai Fjords National Park","description":"Tidewater glaciers calving into the sea, humpbacks and orcas, puffin colonies \u2014 best seen on a day boat tour from Seward harbor. The park protects 40+ glaciers flowing from the Harding Icefield.","officialUrl":"https://www.nps.gov/kefj","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kenai+Fjords+National+Park+Seward+AK","price":"Boat tours $110\u2013$220 (est.)","photos":["assets/pacific/images/seward-ak-coast/attr1-1.jpg","assets/pacific/images/seward-ak-coast/attr1-2.jpg","assets/pacific/images/seward-ak-coast/attr1-3.jpg","assets/pacific/images/seward-ak-coast/attr1-4.jpg"]},{"name":"Alaska SeaLife Center","description":"Alaska's only public aquarium and a working research center: puffins, sea lions, harbor seals, and a giant Pacific octopus. Touch tanks and the seabird aviary are kid favorites.","officialUrl":"https://www.alaskasealife.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Alaska+SeaLife+Center+Seward+AK","price":"$35/adult, $22/child (est.)","photos":["assets/pacific/images/seward-ak-coast/attr2-1.jpg","assets/pacific/images/seward-ak-coast/attr2-2.jpg","assets/pacific/images/seward-ak-coast/attr2-3.jpg","assets/pacific/images/seward-ak-coast/attr2-4.jpg"]},{"name":"Exit Glacier","description":"Kenai Fjords' only road-accessible glacier \u2014 walk the 1-mile loop to the outwash plain and stand near the blue ice. The dated signs show how far it's retreated: a powerful climate lesson.","officialUrl":"https://www.nps.gov/kefj","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Exit+Glacier+Seward+AK","price":"Free (est.)","photos":["assets/pacific/images/seward-ak-coast/attr3-1.jpg","assets/pacific/images/seward-ak-coast/attr3-2.jpg","assets/pacific/images/seward-ak-coast/attr3-3.jpg","assets/pacific/images/seward-ak-coast/attr3-4.jpg"]},{"name":"Resurrection Bay","description":"Seward's stunning fjord: sea otters, bald eagles, and salmon streams right from town. Kayak its coves, hike the coastal trail, or take a half-day wildlife cruise.","officialUrl":"https://www.seward.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Resurrection+Bay+Seward+AK","price":"Free; tours $80\u2013$150 (est.)","photos":["assets/pacific/images/seward-ak-coast/attr4-1.jpg","assets/pacific/images/seward-ak-coast/attr4-2.jpg","assets/pacific/images/seward-ak-coast/attr4-3.jpg","assets/pacific/images/seward-ak-coast/attr4-4.jpg"]}],"restaurants":[{"name":"The Cookery","detail":"Seward's beloved fine-dining spot \u2014 Alaska seafood with a creative twist; book ahead.","price":"$$$"},{"name":"Ray's Waterfront","detail":"Harbor-side classic for halibut fish and chips with boat views.","price":"$$"},{"name":"Chinooks Waterfront Restaurant","detail":"Lively waterfront spot with great chowder and a kids' menu.","price":"$$"}],"rainyDay":["Alaska SeaLife Center (indoors)","Seward Community Library & Museum","Kenai Fjords National Park visitor film"],"driveNotes":"Seward is 2.5 hours south of Anchorage on the stunning Seward Highway \u2014 allow extra time for photo stops. The Alaska Railroad's Coastal Classic train is a spectacular alternative. Book boat tours and summer lodging well ahead; July is peak.","related":["anchorage-ak-city","denali-ak-nature","juneau-ak-city"],"imageAsset":"assets/pacific/images/seward-ak-coast/hero.jpg"}];
